const (
	kindFlag = iota
	kindU64
	kindU32
	kindF64
	kindDur
	kindStr
	kindEnum
	kindMethod
)

type argSpec struct {
	short    string
	long     string
	valName  string // value placeholder, "" for flags
	kind     int
	multi    bool
	possible []string
}

type parsed struct {
	vals map[string][]string
	url  string
}

var specs []argSpec

func init() {
	specs = []argSpec{
