	}
	return -1
}

func specName(i int) string {
	s := specs[i]
	if s.long != "" {
		return s.long
	}
	return s.short
}

func (p *parsed) missingRequiredUsage(used []string, missing []string) string {
	skip := map[string]bool{}
	parts := []string{}
	seen := map[string]bool{}
	render := func(idx int) {
		if seen[idx] {
			return
		}
		seen[idx] = true
		s := specs[idx]
		if s.valName != "" {
			if s.short != "" {
				parts = append(parts, fmt.Sprintf("-%s <%s>", s.short, s.valName))
			} else {
				parts = append(parts, fmt.Sprintf("--%s <%s>", s.long, s.valName))
			}
		} else {
			if s.short != "" && s.long != "" {
				parts = append(parts, "-"+s.short)
			} else if s.long != "" {
				parts = append(parts, "--"+s.long)
			} else {
				parts = append(parts, "-"+s.short)
			}
		}
	}
	for i := range specs {
		name := specName(i)
		isUsed := pos(used, name) >= 0
		if req, ok := requires[name]; ok && isUsed {
			render(i)
			if pos(used, req) < 0 {
				ri := specIndex(req, "")
				if ri >= 0 {
					render(ri)
				}
			}
			continue
		}
		if isUsed {
			render(i)
			continue
		}
		for _, mi := range missing {
			if mi == name {
				// required & missing: only add if not already emitted
				render(i)
			}
		}
	}
	parts = append(parts, "<URL>")
	return "Usage: " + binName() + " " + strings.Join(parts, " ")
}
GOEOF
echo done"}

