	return fmt.Sprintf("error: invalid value '%s' for '%s': %s\n%s", val, arg, reason, tryHelp())
}

func errInvalidEnum(val, arg string, possible []string, hint string) string {
	s := fmt.Sprintf("error: invalid value '%s' for '%s'\n  [possible values: %s]\n", val, arg, strings.Join(possible, ", "))
	if hint != "" {
		s += "\n  tip: a similar value exists: '" + hint + "'\n"
	}
	s += tryHelp()
	return s
}

func unexpectedArg(arg string, tip bool, suggest string) string {
	s := fmt.Sprintf("error: unexpected argument '%s' found\n\n", arg)
	if suggest != "" {
		s += "  tip: a similar argument exists: '" + suggest + "'\n\n"
	} else if tip {
		s += "  tip: to pass '" + arg + "' as a value, use '-- " + arg + "'\n\n"
	}
	if suggest != "" {
		idx := specIndex("", strings.TrimPrefix(suggest, "--"))
		used := []string{}
		if idx >= 0 {
			used = append(used, specName(idx))
		}
		s += usageFor(used, nil) + "\n"
	} else {
		s += "Usage: " + binName() + " [OPTIONS] <URL>\n"
	}
	s += tryHelp()
	return s
}

func missingValueErr(arg string) string {
	return fmt.Sprintf("error: a value is required for '%s' but none was supplied\n%s", arg, tryHelp())
}

func conflictErr(a, b string) string {
	ai := specIndex(a, "")
	bi := specIndex(b, "")
	s := fmt.Sprintf("error: the argument '%s' cannot be used with '%s'\n\n", argDisplay(ai), argDisplay(bi))
	skip := map[string]bool{specName(bi): true}
	s += usageFor([]string{specName(ai), specName(bi), "c"}, skip) + "\n"
	s += tryHelp()
	return s
}

func argDisplay(idx int) string {
	s := specs[idx]
	if s.valName != "" {
		if s.short != "" && s.long != "" {
			return fmt.Sprintf("-%s, --%s <%s>", s.short, s.long, s.valName)
		} else if s.short != "" {
			return fmt.Sprintf("-%s <%s>", s.short, s.valName)
		}
		return fmt.Sprintf("--%s <%s>", s.long, s.valName)
	}
	if s.short != "" && s.long != "" {
		return fmt.Sprintf("-%s, --%s", s.short, s.long)
	} else if s.short != "" {
		return "-" + s.short
	}
	return "--" + s.long
}

func similarArg(name string) string {
	best := ""
	bestScore := 999
	for _, s := range specs {
		if s.long == "" {
			continue
		}
		d := editDistance(name, s.long)
		if d < bestScore {
			bestScore = d
			best = s.long
		}
	}
	if bestScore <= 2 && best != name {
		return "--" + best
	}
	return ""
}

func editDistance(a, b string) int {
	if a == b {
		return 0
	}
	la, lb := len(a), len(b)
	prev := make([]int, lb+1)
	cur := make([]int, lb+1)
	for j := 0; j <= lb; j++ {
		prev[j] = j
	}
	for i := 1; i <= la; i++ {
		cur[0] = i
		for j := 1; j <= lb; j++ {
			cost := 1
			if a[i-1] == b[j-1] {
				cost = 0
			}
			cur[j] = min3(prev[j]+1, cur[j-1]+1, prev[j-1]+cost)
		}
		copy(prev, cur)
	}
	return prev[lb]
}

func min3(a, b, c int) int {
	if b < a {
		a = b
	}
	if c < a {
		a = c
	}
	return a
}

func parseArgs(argv []string) *parsed {
	p := &parsed{vals: map[string][]string{}}
	var used []string
	addUsed := func(name string) {
		if pos(used, name) < 0 {
			used = append(used, name)
		}
	}
	endOfFlags := false
	i := 0
	for i < len(argv) {
		a := argv[i]
		i++
		if endOfFlags {
			if p.url == "" {
				p.url = a
			} else {
				errExit(unexpectedArg(a, false, ""))
			}
			continue
		}
		if a == "--" {
			endOfFlags = true
			continue
		}
		if strings.HasPrefix(a, "--") {
			name := a[2:]
			var inline string
			hasInline := false
			if eq := strings.Index(name, "="); eq >= 0 {
				inline = name[eq+1:]
				name = name[:eq]
				hasInline = true
			}
			idx := specIndex("", name)
			if idx < 0 {
				sug := similarArg(name)
				errExit(unexpectedArg("--"+name, true, sug))
			}
			s := specs[idx]
			if s.kind == kindFlag {
				if hasInline {
					errExit(unexpectedArg("--"+name, true, ""))
				}
				p.vals[specName(idx)] = append(p.vals[specName(idx)], "1")
				addUsed(specName(idx))
				continue
			}
			var v string
			if hasInline {
				v = inline
			} else {
				if i >= len(argv) {
					// clap: reports missing required args (positional)
					errExit(missingRequired([]string{specName(idx)}, used, p))
				}
				v = argv[i]
				i++
			}
			validateAndStore(p, idx, v, specName(idx))
			addUsed(specName(idx))
			continue
		}
		if len(a) > 1 && a[0] == '-' {
			// short cluster
			rest := a[1:]
			for len(rest) > 0 {
				c := rest[0:1]
				idx := specIndex(c, "")
				if idx < 0 {
					errExit(unexpectedArg("-"+c, true, ""))
				}
				s := specs[idx]
				nm := specName(idx)
				if s.kind == kindFlag {
					p.vals[nm] = append(p.vals[nm], "1")
					addUsed(nm)
					rest = rest[1:]
					continue
				}
				var v string
				if len(rest) > 1 {
					v = rest[1:]
					if strings.HasPrefix(v, "=") {
						v = v[1:]
					}
					rest = ""
				} else {
					if i >= len(argv) {
						errExit(missingRequired([]string{nm}, used, p))
					}
					v = argv[i]
					i++
					rest = ""
				}
				validateAndStore(p, idx, v, fmt.Sprintf("-%s <%s>", s.short, s.valName))
				addUsed(nm)
			}
			continue
		}
		// positional
		if p.url == "" {
			p.url = a
		} else {
			errExit(unexpectedArg(a, false, ""))
		}
	}
	// conflicts
	for _, c := range conflicts {
		if p.has(c[0]) && p.has(c[1]) {
			// report the first-appearing one first
			a1, a2 := c[0], c[1]
			if pos(used, a2) < pos(used, a1) {
				a1, a2 = a2, a1
			}
			errExit(conflictErr(a1, a2))
		}
	}
	// requires
	for name, req := range requires {
		if p.has(name) && !p.has(req) {
			errExit(missingRequired([]string{req}, used, p))
		}
	}
	if p.url == "" {
		errExit(missingRequired([]string{"URL"}, used, p))
	}
	return p
}

func missingRequired(missing []string, used []string, p *parsed) string {
	s := "error: the following required arguments were not provided:\n"
	for _, m := range missing {
		if m == "URL" {
			s += "  <URL>\n"
		} else {
			idx := specIndex(m, "")
			s += "  " + argDisplay(idx) + "\n"
		}
	}
	s += "\n"
	s += p.missingRequiredUsage(used, missing) + "\n"
	s += tryHelp()
	return s
}

func validateAndStore(p *parsed, idx int, v string, disp string) {
	s := specs[idx]
	name := specName(idx)
	switch s.kind {
	case kindU64, kindU32:
		n, err := parseCount(v)
		if err != nil {
			errExit(errInvalidValue(v, disp, err.Error()))
		}
		_ = n
	case kindF64:
		if _, err := parseFloatStrict(v); err != nil {
			errExit(errInvalidValue(v, disp, "invalid float literal"))
		}
	case kindDur:
		if _, err := parseDuration(v); err != nil {
			errExit(errInvalidValue(v, disp, err.Error()))
		}
	case kindMethod:
		if !validMethod(v) {
			errExit(errInvalidValue(v, disp, "invalid HTTP method"))
		}
	case kindEnum:
		found := false
		best := ""
		bestScore := 999
		for _, pv := range s.possible {
			if pv == v {
				found = true
				break
			}
			d := editDistance(v, pv)
			if d < bestScore {
				bestScore = d
				best = pv
			}
		}
		if !found {
			hint := ""
			if bestScore <= 2 {
				hint = best
			}
			errExit(errInvalidEnum(v, disp, s.possible, hint))
		}
	}
	p.vals[name] = append(p.vals[name], v)
}

func validMethod(m string) bool {
	if m == "" {
		return false
	}
	for _, c := range m {
		if !(c >= 'A' && c <= 'Z') && !(c >= 'a' && c <= 'z') && !(c >= '0' && c <= '9') {
			return false
		}
	}
	return true
}

func printHelp() {
	fmt.Printf(helpText, binName())
}

func printVersion() {
	fmt.Printf("oha %s\n", version)
}

var version = "1.12.1"

func fatalErr(msg string) {
	fmt.Fprintf(os.Stderr, "Error: %s\n", msg)
	os.Exit(1)
}
