package main

import (
	"errors"
	"fmt"
	"strconv"
	"strings"
)

// parseCount parses numbers like "200", "10k", "1m"
func parseCount(s string) (uint64, error) {
	if s == "" {
		return 0, errors.New("invalid digit found in string")
	}
	mult := uint64(1)
	t := s
	lower := strings.ToLower(s)
	if strings.HasSuffix(lower, "k") {
		mult = 1000
		t = t[:len(t)-1]
	} else if strings.HasSuffix(lower, "m") {
		mult = 1000000
		t = t[:len(t)-1]
	}
	if t == "" {
		return 0, errors.New("invalid digit found in string")
	}
	n, err := strconv.ParseUint(t, 10, 64)
	if err != nil {
		if strings.Contains(err.Error(), "invalid") || strings.Contains(err.Error(), "syntax") {
			return 0, errors.New("invalid digit found in string")
		}
		return 0, errors.New("number too large to fit in target type")
	}
	return n * mult, nil
}

func parseFloatStrict(s string) (float64, error) {
	if s == "" {
		return 0, errors.New("invalid float literal")
	}
	f, err := strconv.ParseFloat(s, 64)
	if err != nil {
		return 0, errors.New("invalid float literal")
	}
	return f, nil
}

var unitMultipliers = []struct {
	names  []string
	nanos  uint64
}{
	{[]string{"ns", "nsec", "nanosecond", "nanoseconds", "nanos"}, 1},
	{[]string{"us", "usec", "microsecond", "microseconds", "micros", "\u00b5s", "\u03bcs"}, 1000},
	{[]string{"ms", "msec", "millisecond", "milliseconds", "millis"}, 1000000},
	{[]string{"s", "sec", "secs", "second", "seconds"}, 1000000000},
	{[]string{"min", "mins", "minute", "minutes"}, 60 * 1000000000},
	{[]string{"h", "hr", "hour", "hours"}, 3600 * 1000000000},
	{[]string{"d", "day", "days"}, 86400 * 1000000000},
	{[]string{"w", "week", "weeks"}, 604800 * 1000000000},
	{[]string{"M", "month", "months"}, 2629800 * 1000000000},
	{[]string{"y", "year", "years"}, 31557600 * 1000000000},
}

func findUnit(u string) (uint64, bool) {
	for _, um := range unitMultipliers {
		for _, n := range um.names {
			if n == u {
				return um.nanos, true
			}
		}
	}
	// variations: "SEC", "SECS", "SEC", "Sec", "MS", etc (case-insensitive)
	lu := strings.ToLower(u)
	for _, um := range unitMultipliers {
		for _, n := range um.names {
			if strings.ToLower(n) == lu {
				return um.nanos, true
			}
		}
	}
	return 0, false
}

var unknownUnitFmt = "unknown time unit %q, supported units: ns, us/\u00b5s, ms, sec, min, hours, days, weeks, months, years (and few variations)"

// parseDuration mimics humantime::parse_duration errors
func parseDuration(s string) (uint64, error) {
	if s == "" {
		return 0, errors.New("expected number at 0")
	}
	i := 0
	var total uint64
	first := true
	for i < len(s) {
		// skip whitespace
		for i < len(s) && (s[i] == ' ' || s[i] == '\t') {
			i++
		}
		if i >= len(s) {
			break
		}
		start := i
		for i < len(s) && s[i] >= '0' && s[i] <= '9' {
			i++
		}
		if i == start {
			return 0, errors.New(fmt.Sprintf("expected number at %d", i))
		}
		numStr := s[start:i]
		// fractional part
		var fracDigits string
		if i < len(s) && s[i] == '.' {
			j := i + 1
			for j < len(s) && s[j] >= '0' && s[j] <= '9' {
				j++
			}
			fracDigits = s[i+1 : j]
			i = j
		}
		// unit
		ustart := i
		for i < len(s) && !isDigit(s[i]) {
			i++
		}
		u := s[ustart:i]
		if u == "" {
			return 0, errors.New("time unit needed, for example 10sec or 20ms")
		}
		mult, ok := findUnit(u)
		if !ok {
			return 0, errors.New(fmt.Sprintf(unknownUnitFmt, u))
		}
		n, err := strconv.ParseUint(numStr, 10, 64)
		if err != nil {
			return 0, errors.New("number is too large or cannot be represented without a lack of precision (values below 1ns are not supported)")
		}
		v, err := mulU64(n, mult)
		if err != nil {
			return 0, errors.New("number is too large or cannot be represented without a lack of precision (values below 1ns are not supported)")
		}
		if fracDigits != "" {
			fd, err2 := strconv.ParseUint(fracDigits, 10, 64)
			if err2 == nil {
				scale := uint64(1)
				for k := 0; k < len(fracDigits); k++ {
					scale *= 10
				}
				fv := fd * mult / scale
				v += fv
			}
		}
		total += v
		first = false
	}
	_ = first
	return total, nil
}

func mulU64(a, b uint64) (uint64, error) {
	if a == 0 || b == 0 {
		return 0, nil
	}
	r := a * b
	if r/b != a {
		return 0, errors.New("overflow")
	}
	return r, nil
}

func isDigit(c byte) bool { return c >= '0' && c <= '9' }
GOEOF
