package main

import (
	"bufio"
	"crypto/tls"
	"crypto/x509"
	"errors"
	"fmt"
	"io"
	"net"
	"net/url"
	"os"
	"sort"
	"strconv"
	"strings"
	"time"
)

type target struct {
	raw       string // original URL string
	scheme    string
	host      string // host (without port)
	port      string
	path      string // path+query as in URL
	abs       string // absolute URL form for proxy
}

type reqOpts struct {
	method      string
	headers     [][2]string
	body        []byte
	httpVersion string // "0.9","1.0","1.1","2","3"
	redirect    int
	timeout     time.Duration
}

type respInfo struct {
	status  int
	version string
	headers [][2]string
	body    []byte
}

type connTimes struct {
	dns   time.Duration
	dial  time.Duration // dial + tls
}

type client struct {
	cfg        *config
	resolved   []net.IP
	dnsDur     time.Duration // cached dns duration for new connections
	lookupOnly bool          // no-pre-lookup: do not cache
}

func (t *target) hostPort() string {
	if t.port != "" {
		return net.JoinHostPort(t.host, t.port)
	}
	return t.host
}

// resolve performs DNS lookup honoring ipv4/ipv6/connect-to
func (c *client) resolve(t *target) ([]net.IP, time.Duration, error) {
	if c.cfg.noPreLookup == false {
		if c.resolved != nil {
			return c.resolved, 0, nil
		}
	}
	start := time.Now()
	ips, err := c.lookup(t.host)
	d := time.Since(start)
	if err != nil {
