func (t *target) hostPort() string {
	if t.port != "" {
		return net.JoinHostPort(t.host, t.port)
	}
	return t.host
}

// resolve performs DNS lookup honoring ipv4/ipv6/connect-to
func (c *client) resolve(t *target) ([]net.IP, time.Duration, error) {
	if c.cfg.noPreLookup == false {
		if c.resolved != nil {
			return c.resolved, 0, nil
		}
	}
	start := time.Now()
	ips, err := c.lookup(t.host)
	d := time.Since(start)
	if err != nil {
		return nil, 0, err
	}
	if c.cfg.noPreLookup == false {
		c.resolved = ips
	}
	return ips, d, nil
}

func (c *client) lookup(host string) ([]net.IP, error) {
	// connect-to override
	for _, ct := range c.cfg.connectTo {
		parts := strings.Split(ct, ":")
		if len(parts) == 4 {
			if parts[0] == host {
				ip := net.ParseIP(parts[2])
				if ip != nil {
					return []net.IP{ip}, nil
				}
			}
		}
	}
	if ip := net.ParseIP(host); ip != nil {
		return []net.IP{ip}, nil
	}
	if c.cfg.ipv4 && !c.cfg.ipv6 {
		return net.LookupIP(host) // filtered below
	}
	ips, err := net.LookupIP(host)
	if err != nil {
		// mimic rust dns error
		qt := "AAAA"
		if c.cfg.ipv4 && !c.cfg.ipv6 {
			qt = "A"
		}
		return nil, fmt.Errorf("no records found for Query { name: Name(\"%s.\"), query_type: %s, query_class: IN }", host, qt)
	}
	var out []net.IP
	var v4, v6 []net.IP
	for _, ip := range ips {
		if ip4 := ip.To4(); ip4 != nil {
			v4 = append(v4, ip4)
		} else {
			v6 = append(v6, ip)
		}
	}
	if c.cfg.ipv4 && !c.cfg.ipv6 {
		out = v4
	} else if c.cfg.ipv6 && !c.cfg.ipv4 {
		out = v6
	} else {
		// prefer ipv6 first (matching oha which reports AAAA error)
		out = append(v6, v4...)
	}
	if len(out) == 0 {
		return nil, fmt.Errorf("no records found for Query { name: Name(\"%s.\"), query_type: AAAA, query_class: IN }", host)
	}
	return out, nil
}

func dialAddr(c *client, ip net.IP, port string, unixSock string, timeout time.Duration) (net.Conn, error) {
	if unixSock != "" {
		return net.DialTimeout("unix", unixSock, timeout)
	}
	return net.DialTimeout("tcp", net.JoinHostPort(ip.String(), port), timeout)
}

func tlsConfig(c *client, host string) (*tls.Config, error) {
	cfg := &tls.Config{ServerName: host, MinVersion: tls.VersionTLS10}
	if c.cfg.insecure {
		cfg.InsecureSkipVerify = true
	}
	pool, err := x509.SystemCertPool()
	if err != nil {
		pool = x509.NewCertPool()
	}
	if c.cfg.cacert != "" {
	 pem, err := os.ReadFile(c.cfg.cacert)
		if err != nil {
			return nil, err
		}
		pool.AppendCertsFromPEM(pem)
	}
	cfg.RootCAs = pool
	if c.cfg.cert != "" && c.cfg.key != "" {
		cert, err := tls.LoadX509KeyPair(c.cfg.cert, c.cfg.key)
		if err != nil {
			return nil, err
		}
		cfg.Certificates = []tls.Certificate{cert}
	}
	cfg.NextProtos = []string{"http/1.1"}
	if c.cfg.httpVersion == "2" {
		cfg.NextProtos = []string{"h2", "http/1.1"}
	}
	return cfg, nil
}

// sendRequest writes request and reads response over conn
func sendRequest(w *bufio.Writer, r *bufio.Reader, method string, uri string, host string, hdrs [][2]string, body []byte, version string) (*respInfo, error) {
	reqline := fmt.Sprintf("%s %s HTTP/1.1\r\n", method, uri)
	if version == "0.9" {
		reqline = fmt.Sprintf("%s %s\r\n", method, uri)
	} else if version == "1.0" {
		reqline = fmt.Sprintf("%s %s HTTP/1.0\r\n", method, uri)
	}
	if _, err := w.WriteString(reqline); err != nil {
		return nil, err
	}
	for _, h := range hdrs {
		if _, err := w.WriteString(h[0] + ": " + h[1] + "\r\n"); err != nil {
			return nil, err
		}
	}
	_ = host
	if body != nil {
		w.WriteString("content-length: " + strconv.Itoa(len(body)) + "\r\n")
	} else if method != "GET" && method != "HEAD" {
		w.WriteString("content-length: 0\r\n")
	}
	if version != "0.9" {
		w.WriteString("\r\n")
	}
	if body != nil {
		w.Write(body)
	}
	if err := w.Flush(); err != nil {
		return nil, err
	}
	if version == "0.9" {
		b, err := io.ReadAll(r)
		if err != nil && len(b) == 0 {
			return nil, err
		}
		return &respInfo{status: 200, version: "HTTP/0.9", body: b}, nil
	}
	status, hdrs2, err := readRespHeaders(r)
	if err != nil {
		return nil, err
	}
	// read body
	bodyBytes, err := readBody(r, hdrs2, status, method)
	if err != nil {
		return nil, err
	}
	return &respInfo{status: status, version: "HTTP/1.1", headers: hdrs2, body: bodyBytes}, nil
}

func readRespHeaders(r *bufio.Reader) (int, [][2]string, error) {
	line, err := readLine(r)
	if err != nil {
		return 0, nil, err
	}
	parts := strings.SplitN(line, " ", 3)
	if len(parts) < 2 {
		return 0, nil, errors.New("invalid response")
	}
	code := 0
	for _, p := range strings.Fields(parts[1]) {
		if n, e := strconv.Atoi(p); e == nil {
			code = n
			break
		}
	}
	hdrs := [][2]string{}
	for {
		h, err := readLine(r)
		if err != nil {
			return 0, nil, err
		}
		if h == "" {
			break
		}
		ci := strings.Index(h, ":")
		if ci < 0 {
			continue
		}
		hdrs = append(hdrs, [2]string{strings.ToLower(strings.TrimSpace(h[:ci])), strings.TrimSpace(h[ci+1:])})
	}
	return code, hdrs, nil
}

func readLine(r *bufio.Reader) (string, error) {
	s, err := r.ReadString('\n')
	if err != nil {
		return "", err
	}
	return strings.TrimRight(s, "\r\n"), nil
}

func readBody(r *bufio.Reader, hdrs [][2]string, status int, method string) ([]byte, error) {
	if status == 204 || status == 304 || method == "HEAD" {
		return nil, nil
	}
	var te, cl string
	for _, h := range hdrs {
		if h[0] == "transfer-encoding" {
			te = h[1]
		}
		if h[0] == "content-length" {
			cl = h[1]
		}
	}
	if strings.Contains(strings.ToLower(te), "chunked") {
		var out []byte
		for {
			line, err := readLine(r)
			if err != nil {
				return out, nil
			}
			line = strings.TrimSpace(line)
			if line == "" {
				continue
			}
			semi := strings.Index(line, ";")
			if semi >= 0 {
				line = line[:semi]
			}
			n, err := strconv.ParseInt(line, 16, 64)
			if err != nil {
				return out, nil
			}
			if n == 0 {
				// trailing headers
				for {
					h, err := readLine(r)
					if err != nil || h == "" {
						break
					}
				}
				return out, nil
			}
			buf := make([]byte, n)
			if _, err := io.ReadFull(r, buf); err != nil {
				return out, nil
			}
			out = append(out, buf...)
			// trailing CRLF
			readLine(r)
		}
	}
	if cl != "" {
		n, err := strconv.ParseInt(cl, 10, 64)
		if err != nil || n < 0 {
			return nil, nil
		}
		buf := make([]byte, n)
		if _, err := io.ReadFull(r, buf); err != nil {
			return nil, err
		}
		return buf, nil
	}
	// read until EOF
	b, err := io.ReadAll(r)
	if err != nil && len(b) == 0 {
		return nil, err
	}
	return b, nil
}

func sortHeaders(h [][2]string) {}

func headerGet(hdrs [][2]string, name string) (string, bool) {
	for _, h := range hdrs {
		if strings.EqualFold(h[0], name) {
			return h[1], true
		}
	}
	return "", false
}

// normalize URL into target
func makeTarget(raw string) (*target, error) {
	u, err := url.Parse(raw)
	if err != nil {
		return nil, err
	}
	if !u.IsAbs() {
		return nil, errors.New("relative URL without a base")
	}
	t := &target{raw: raw, scheme: u.Scheme, host: u.Hostname(), path: u.RequestURI()}
	switch u.Scheme {
	case "http":
		t.port = u.Port()
		if t.port == "" {
			t.port = "80"
		}
	case "https":
		t.port = u.Port()
		if t.port == "" {
			t.port = "443"
		}
	default:
		return nil, errors.New("unsupported scheme")
	}
	t.abs = u.String()
	return t, nil
}

func splitConnectTo(ct string) (string, string, string, string, bool) {
	parts := strings.Split(ct, ":")
	if len(parts) == 4 {
		return parts[0], parts[1], parts[2], parts[3], true
	}
	return "", "", "", "", false
}

func pickConnectTo(list []string, host, port string) (string, string, bool) {
	var cands [][2]string
	for _, ct := range list {
		oh, op, th, tp, ok := splitConnectTo(ct)
		if !ok {
			continue
		}
		if oh == host && (op == port || op == "") {
			cands = append(cands, [2]string{th, tp})
		}
	}
	if len(cands) == 0 {
		return "", "", false
	}
	i := int(time.Now().UnixNano()) % len(cands)
	return cands[i][0], cands[i][1], true
}

func strPtr(s string) *string { return &s }

func minI(a, b int) int {
	if a < b {
		return a
	}
	return b
}

func maxI(a, b int) int {
	if a > b {
		return a
	}
	return b
}

var _ = sort.Strings
var _ = errors.New
GOEOF
echo ok"}

