{"command": "cd /workspace/src && cat > request.go <<'GOEOF'
package main

import (
	"crypto/hmac"
	"crypto/sha256"
	"encoding/base64"
	"encoding/hex"
	"fmt"
	"os"
	"strings"
	"time"
)

const userAgent = "oha/" + version

type bodySource struct {
	kind    int // 0 none, 1 fixed, 2 lines, 3 file
	fixed   []byte
	lines   [][]byte
	file    []byte
	fileIdx int
}

func newBodySource(c *config) (*bodySource, error) {
	b := &bodySource{}
	if c.bodyString != "" {
		b.kind = 1
		b.fixed = []byte(c.bodyString)
		return b, nil
	}
	if c.bodyPath != "" {
		data, err := os.ReadFile(c.bodyPath)
		if err != nil {
			return nil, err
		}
		b.kind = 3
		b.file = data
		return b, nil
	}
	if c.bodyPathLines != "" {
		data, err := os.ReadFile(c.bodyPathLines)
		if err != nil {
			return nil, err
		}
		b.kind = 2
		lines := strings.Split(strings.TrimRight(string(data), "\n"), "\n")
		for _, l := range lines {
			b.lines = append(b.lines, []byte(l))
		}
		if len(b.lines) == 0 {
			b.kind = 1
			b.fixed = nil
		}
		return b, nil
	}
	return b, nil
}

func (b *bodySource) next() []byte {
	switch b.kind {
	case 1:
		return b.fixed
	case 3:
		return b.file
	case 2:
		if len(b.lines) == 0 {
			return nil
		}
		i := int(randUint64() % uint64(len(b.lines)))
		return b.lines[i]
	}
	return nil
}

var randState uint64 = 0x9E3779B97F4A7C15

func randUint64() uint64 {
	randState ^= randState << 13
	randState ^= randState >> 7
	randState ^= randState << 17
	return randState
}

func seedRand() {
	randState = uint64(time.Now().UnixNano()) | 1
}

func b64std(s string) string {
	return base64.StdEncoding.EncodeToString([]byte(s))
}

// buildHeaders returns headers in oha's order
func buildHeaders(c *config, hostHeader string, body []byte, formBoundary string) [][2]string {
	var hdrs [][2]string
	accept := c.accept
	if accept == "" {
		accept = "*/*"
	}
	if c.awsSigv4 != "" {
		// aws sigv4 headers first
		hdrs = append(hdrs, sigv4Headers(c, hostHeader, body)...)
	}
	hdrs = append(hdrs, [2]string{"accept", accept})
	if !c.disableCompression {
		hdrs = append(hdrs, [2]string{"accept-encoding", "gzip, compress, deflate, br"})
	}
	hdrs = append(hdrs, [2]string{"user-agent", userAgent})
	if formBoundary != "" {
		hdrs = append(hdrs, [2]string{"content-type", "multipart/form-data; boundary=" + formBoundary})
	} else if c.contentType != "" {
		hdrs = append(hdrs, [2]string{"content-type", c.contentType})
	}
	if c.awsSigv4 == "" && c.basicAuth != "" {
		if strings.Contains(c.basicAuth, ":") {
			parts := strings.SplitN(c.basicAuth, ":", 2)
			hdrs = append(hdrs, [2]string{"authorization", "Basic " + b64std(c.basicAuth)})
			_ = parts
		} else {
			hdrs = append(hdrs, [2]string{"authorization", "Bearer " + c.basicAuth})
		}
	}
	for _, h := range c.headers {
		ci := strings.Index(h, ":")
		if ci < 0 {
			continue
		}
		name := strings.TrimSpace(h[:ci])
		val := strings.TrimSpace(h[ci+1:])
		hdrs = append(hdrs, [2]string{strings.ToLower(name), val})
	}
	hdrs = append(hdrs, [2]string{"host", hostHeader})
	return hdrs
}

func hmacSHA256(key, data []byte) []byte {
	m := hmac.New(sha256.New, key)
	m.Write(data)
	return m.Sum(nil)
}

func sha256hex(b []byte) string {
	s := sha256.Sum256(b)
	return hex.EncodeToString(s[:])
}

func sigv4Headers(c *config, hostHeader string, body []byte) [][2]string {
	// format: aws:amz:region:service
	parts := strings.Split(c.awsSigv4, ":")
	var region, service string
	if len(parts) >= 4 {
		region = parts[2]
		service = parts[3]
	} else if len(parts) == 3 {
		region = parts[1]
		service = parts[2]
	}
	cred := strings.SplitN(c.basicAuth, ":", 2)
	accessKey := ""
	secretKey := ""
	if len(cred) == 2 {
		accessKey, secretKey = cred[0], cred[1]
	} else {
		accessKey = c.basicAuth
	}
	now := time.Now().UTC()
	amzDate := now.Format("20060102T150405Z")
	dateShort := now.Format("20060102")
	// host for signing: url host without port
	signHost := hostHeader
	if i := strings.LastIndex(signHost, ":"); i >= 0 {
		if p := signHost[i+1:]; isNumeric(p) {
			signHost = signHost[:i]
		}
	}
	var hdrs [][2]string
	hdrs = append(hdrs, [2]string{"x-amz-date", amzDate})
	hdrs = append(hdrs, [2]string{"host", signHost})
	if c.awsSession != "" {
		hdrs = append(hdrs, [2]string{"x-amz-security-token", c.awsSession})
	}
	hdrs = append(hdrs, [2]string{"content-length", fmt.Sprintf("%d", len(body))})
	// canonical request
	signed := []string{"content-length", "host", "x-amz-date"}
	if c.awsSession != "" {
		signed = append(signed, "x-amz-security-token")
	}
	// sort
	for i := 0; i < len(signed); i++ {
		for j := i + 1; j < len(signed); j++ {
			if signed[j] < signed[i] {
				signed[i], signed[j] = signed[j], signed[i]
			}
		}
	}
	var chs []string
	for _, h := range signed {
		v := ""
		for _, hh := range hdrs {
			if hh[0] == h {
				v = hh[1]
				break
			}
		}
		chs = append(chs, h+":"+v)
	}
	canonicalHeaders := strings.Join(chs, "\n")
	canonicalRequest := "GET\n/\n\n" + canonicalHeaders + "\n\n" + strings.Join(signed, ";") + "\n" + sha256hex(body)
	scope := dateShort + "/" + region + "/" + service + "/aws4_request"
	stringToSign := "AWS4-HMAC-SHA256\n" + amzDate + "\n" + scope + "\n" + sha256hex([]byte(canonicalRequest))
	kDate := hmacSHA256([]byte("AWS4"+secretKey), []byte(dateShort))
	kRegion := hmacSHA256(kDate, []byte(region))
	kService := hmacSHA256(kRegion, []byte(service))
	kSigning := hmacSHA256(kService, []byte("aws4_request"))
	sig := hex.EncodeToString(hmacSHA256(kSigning, []byte(stringToSign)))
	auth := fmt.Sprintf("AWS4-HMAC-SHA256 Credential=%s/%s,SignedHeaders=%s,Signature=%s", accessKey, scope, strings.Join(signed, ";"), sig)
	hdrs = append(hdrs, [2]string{"authorization", auth})
	return hdrs
}

func isNumeric(s string) bool {
	if s == "" {
		return false
	}
	for i := 0; i < len(s); i++ {
		if s[i] < '0' || s[i] > '9' {
			return false
		}
	}
	return true
}

func buildMultipart(c *config) ([]byte, string, error) {
	boundary := "----formdata-oha-" + randomHex32()
	var parts []string
	for _, f := range c.form {
		if strings.HasPrefix(f, "@") {
			path := f[1:]
			data, err := os.ReadFile(path)
			if err != nil {
				return nil, "", err
			}
			name := baseName(path)
			parts = append(parts, "Content-Disposition: form-data; name=\""+name+"\"; filename=\""+name+"\"\r\n\r\n"+string(data))
		} else {
			ci := strings.Index(f, "=")
			if ci < 0 {
				name := f
				parts = append(parts, "Content-Disposition: form-data; name=\""+name+"\"\r\n\r\n")
			} else {
				name := f[:ci]
				val := f[ci+1:]
				if strings.HasPrefix(val, "@") {
					data, err := os.ReadFile(val[1:])
					if err != nil {
						return nil, "", err
					}
					parts = append(parts, "Content-Disposition: form-data; name=\""+name+"\"; filename=\""+baseName(val[1:])+"\"\r\n\r\n"+string(data))
				} else {
					parts = append(parts, "Content-Disposition: form-data; name=\""+name+"\"\r\n\r\n"+val)
				}
			}
		}
	}
	var sb strings.Builder
	for _, p := range parts {
		sb.WriteString("--" + boundary[2:] + "\r\n")
		sb.WriteString(p)
		sb.WriteString("\r\n")
	}
	sb.WriteString("--" + boundary[2:] + "--\r\n")
	return []byte(sb.String()), boundary, nil
}

func baseName(p string) string {
	i := strings.LastIndex(p, "/")
	if i >= 0 {
		return p[i+1:]
	}
	return p
}

func randomHex32() string {
	const hexd = "0123456789abcdef"
	var sb strings.Builder
	for i := 0; i < 32; i++ {
		sb.WriteByte(hexd[randUint64()%16])
	}
	return sb.String()
}
GOEOF
echo ok"}

