package main

import (
	"math"
	"sort"
)

type record struct {
	start      float64 // seconds from run start
	dns        float64
	dnsDial    float64
	respDelay  float64
	duration   float64
	bytes      uint64
	status     int
	err        string
	url        string
	startLC    float64
	end        float64
	isDeadline bool
}

type dist struct {
	vals []float64
	sorted []float64
	dirty bool
}

func (d *dist) add(v float64) {
	d.vals = append(d.vals, v)
	d.dirty = true
}

func (d *dist) n() int { return len(d.vals) }

func (d *dist) sortVals() []float64 {
	if d.dirty || d.sorted == nil {
		d.sorted = append([]float64(nil), d.vals...)
		sort.Float64s(d.sorted)
		d.dirty = false
	}
	return d.sorted
}

func (d *dist) mean() float64 {
	if len(d.vals) == 0 {
		return math.NaN()
	}
	s := 0.0
	for _, v := range d.vals {
		s += v
	}
	return s / float64(len(d.vals))
}

func (d *dist) stddev() float64 {
	n := float64(len(d.vals))
	if n < 1 {
		return math.NaN()
	}
	m := d.mean()
	var s2, s float64
	for _, v := range d.vals {
		s2 += v * v
		s += v
	}
	variance := s2/(n-1) - (s*s/n)/(n-1)
	return math.Sqrt(variance)
}

func (d *dist) min() float64 {
	if len(d.vals) == 0 {
		return math.Inf(1)
	}
	return d.sortVals()[0]
}

func (d *dist) max() float64 {
	if len(d.vals) == 0 {
		return math.Inf(-1)
	}
	s := d.sortVals()
	return s[len(s)-1]
}

// percentile p in [0,1]
func (d *dist) percentile(p float64) float64 {
	s := d.sortVals()
	if len(s) == 0 {
		return math.NaN()
	}
	idx := int(math.Floor(p * float64(len(s))))
	if idx < 0 {
		idx = 0
	}
	if idx >= len(s) {
		idx = len(s) - 1
	}
	return s[idx]
}

type stats struct {
	records   []*record
	total     float64 // wall clock seconds
	startTime float64
	success   int
	errCount  int
	deadlineAborts int
	statusCodes map[int]int
	errDist      map[string]int
	latency    dist
	dns        dist
	dnsDial    dist
	respDelay  dist
	respDelayNoRedirect dist
	dnsNoConn  dist
	rpsTimes   []float64
	totalData  uint64
	urls       map[string]bool
}

func newStats() *stats {
	return &stats{
		statusCodes: map[int]int{},
		errDist:     map[string]int{},
		urls:        map[string]bool{},
	}
}

func (s *stats) add(r *record) {
	s.records = append(s.records, r)
	if r.err == "" {
		s.success++
		s.statusCodes[r.status]++
		s.totalData += r.bytes
		s.latency.add(r.duration)
		if !s.hasRedirect[r.url] {
			s.respDelay.add(r.respDelay)
		} else {
			s.respDelayNoRedirect.add(r.respDelay)
		}
		if r.dnsDial > 0 {
			s.dnsDial.add(r.dnsDial)
			s.dns.add(r.dns)
		}
		s.rpsTimes = append(s.rpsTimes, r.end)
	} else {
		if r.isDeadline {
			s.deadlineAborts++
		} else {
			s.errCount++
		}
		s.errDist[r.err]++
	}
}

var _ = math.Sqrt
GOEOF
echo ok"}

