package main

import (
	"fmt"
	"math"
	"strings"
)

func fmtF(v float64) string {
	if math.IsNaN(v) {
		return "NaN"
	}
	if math.IsInf(v, 1) {
		return "inf"
	}
	if math.IsInf(v, -1) {
		return "-inf"
	}
	return fmt.Sprintf("%v", v)
}

// time unit helpers
var unitToNanos = map[string]float64{
	"ns":  1,
	"us":  1e3,
	"ms":  1e6,
	"sec": 1e9,
	"min": 60e9,
	"hr":  3600e9,
}

func pickUnit(maxNanos float64) string {
	if math.IsNaN(maxNanos) {
		return "ns"
	}
	if math.IsInf(maxNanos, 1) || math.IsInf(maxNanos, -1) {
		return "ns"
	}
	if maxNanos >= 3600e9 {
		return "hr"
	}
	if maxNanos >= 60e9 {
		return "min"
	}
	if maxNanos >= 1e9 {
		return "sec"
	}
	if maxNanos >= 1e6 {
		return "ms"
	}
	if maxNanos >= 1e3 {
		return "us"
	}
	return "ns"
}

// formatTime formats seconds with given unit, 4 decimals
func formatTime(seconds float64, unit string) string {
	nanos := seconds * 1e9
	scale := unitToNanos[unit]
	return fmt.Sprintf("%.4f %s", nanos/scale, unit)
}

func unitLabel(unit string) string { return unit }

func formatBytes(n float64) string {
	if n < 1024 {
		return fmt.Sprintf("%d B", int64(n))
	}
	units := []string{"KiB", "MiB", "GiB", "TiB", "PiB"}
	v := n
	for _, u := range units {
		v /= 1024
		if v < 1024 {
			return fmt.Sprintf("%.2f %s", v, u)
		}
	}
	return fmt.Sprintf("%.2f EiB", v/1024)
}

// histogram over successful latencies (seconds)
type histBucket struct {
	label string
	val   float64
	count int
}

func buildHistogram(d *dist, unit string) []histBucket {
	if d.n() == 0 {
		// NaN buckets
		b := []histBucket{}
		for i := 0; i < 11; i++ {
			b = append(b, histBucket{label: formatLabel(math.NaN(), unit), val: math.NaN()})
		}
		return b
	}
	mn := d.min()
	mx := d.max()
	step := (mx - mn) / 10
	s := d.sortVals()
	out := make([]histBucket, 0, 11)
	for i := 0; i < 11; i++ {
		var bound float64
		if i == 0 {
			bound = mn
		} else {
			bound = mn + step*float64(i)
			if i == 10 {
				bound = mx
			}
		}
		out = append(out, histBucket{label: formatLabel(bound, unit), val: bound})
	}
	// count: bucket i covers [bound_i, bound_{i+1})
	idx := 0
	for _, v := range s {
		for idx < 10 && (v > out[idx].val && !(idx == 10) ) {
			idx++
		}
		_ = idx
		break
	}
	// recompute counts properly
	counts := make([]int, 11)
	for _, v := range s {
		// find bucket: largest i such that bound_i <= v, capped at 10
		i := 0
		for i < 10 && out[i+1].val <= v {
			i++
		}
		// handle equal boundaries: count into last matching bucket
		if i < 10 {
			for i < 10 && out[i+1].val == v {
				i++
			}
		}
		if i > 10 {
			i = 10
		}
		counts[i]++
	}
	for i := range out {
		out[i].count = counts[i]
	}
	return out
}

func formatLabel(v float64, unit string) string {
	return fmt.Sprintf("%5.3f %s", v, unit)
}

func renderHistogram(b []histBucket, sb *strings.Builder) {
	maxCount := 0
	for _, h := range b {
		if h.count > maxCount {
			maxCount = h.count
		}
	}
	countWidth := len(fmt.Sprintf("%d", maxCount)) + 3
	labelWidth := 0
	for _, h := range b {
		if len(h.label) > labelWidth {
			labelWidth = len(h.label)
		}
	}
	labelWidth += 2
	for _, h := range b {
		bar := ""
		if maxCount > 0 && h.count > 0 {
			w := int(float64(h.count) / float64(maxCount) * 32)
			bar = strings.Repeat("\u25a0", w)
		}
		cnt := fmt.Sprintf("[%d]", h.count)
		if len(cnt) < countWidth {
			cnt += strings.Repeat(" ", countWidth-len(cnt))
		}
		lab := h.label
		if len(lab) < labelWidth {
			lab = strings.Repeat(" ", labelWidth-len(lab)) + lab
		}
		fmt.Fprintf(sb, "%s %s|%s\n", lab, cnt, bar)
	}
}

var percentileNames = []string{"10.00%", "25.00%", "50.00%", "75.00%", "90.00%", "95.00%", "99.00%", "99.90%", "99.99%"}
var percentilePs = []float64{0.10, 0.25, 0.50, 0.75, 0.90, 0.95, 0.99, 0.999, 0.9999}

func renderDistribution(d *dist, unit string, title string, sb *strings.Builder) {
	fmt.Fprintf(sb, "%s:\n", title)
	for i, name := range percentileNames {
		v := d.percentile(percentilePs[i])
		fmt.Fprintf(sb, "  %s in %s\n", name, fmtTimePrec4(v, unit))
	}
}

func fmtTimePrec4(seconds float64, unit string) string {
	nanos := seconds * 1e9
	scale := unitToNanos[unit]
	if math.IsNaN(nanos) {
		return "NaN " + unit
	}
	if math.IsInf(nanos, 1) {
		return "inf " + unit
	}
	if math.IsInf(nanos, -1) {
		return "-inf " + unit
	}
	return fmt.Sprintf("%.4f %s", nanos/scale, unit)
}

func fmtTimeLabel(v float64, unit string) string {
	return fmt.Sprintf("%5.3f %s", v, unit)
}

// detail distribution rows: name, average, fastest, slowest
type detailRow struct {
	name    string
	average float64
	fastest float64
	slowest float64
}

func detailRows(s *stats) []detailRow {
	rows := []detailRow{
		{"DNS+dialup", s.dnsDial.mean(), s.dnsDial.min(), s.dnsDial.max()},
		{"DNS-lookup", s.dns.mean(), s.dns.min(), s.dns.max()},
	}
	return rows
}
GOEOF
echo ok"}

