package main

import (
	"fmt"
	"math"
	"strconv"
	"strings"
)

func fmtF(v float64) string {
	if math.IsNaN(v) {
		return "NaN"
	}
	if math.IsInf(v, 1) {
		return "inf"
	}
	if math.IsInf(v, -1) {
		return "-inf"
	}
	return strconv.FormatFloat(v, 'f', -1, 64)
}

func fmtFJSON(v float64) string {
	if math.IsNaN(v) || math.IsInf(v, 0) {
		return "null"
	}
	s := strconv.FormatFloat(v, 'f', -1, 64)
	if !strings.ContainsAny(s, ".eE") {
		s += ".0"
	}
	return s
}

var unitToNanos = map[string]float64{
	"ns":  1,
	"us":  1e3,
	"ms":  1e6,
	"sec": 1e9,
	"min": 60e9,
	"hr":  3600e9,
}

func pickUnit(maxNanos float64) string {
	if math.IsNaN(maxNanos) || math.IsInf(maxNanos, 0) {
		return "ns"
	}
	if maxNanos >= 3600e9 {
		return "hr"
	}
	if maxNanos >= 60e9 {
		return "min"
	}
	if maxNanos >= 1e9 {
		return "sec"
	}
	if maxNanos >= 1e6 {
		return "ms"
	}
	if maxNanos >= 1e3 {
		return "us"
	}
	return "ns"
}

func formatTime(seconds float64, unit string) string {
	nanos := seconds * 1e9
	scale := unitToNanos[unit]
	if math.IsNaN(nanos) {
		return "NaN " + unit
	}
	if math.IsInf(nanos, 1) {
		return "inf " + unit
	}
	if math.IsInf(nanos, -1) {
		return "-inf " + unit
	}
	return fmt.Sprintf("%.4f %s", nanos/scale, unit)
}

func formatBytes(n float64) string {
	if n < 1024 {
		return fmt.Sprintf("%d B", int64(n))
	}
	units := []string{"KiB", "MiB", "GiB", "TiB", "PiB"}
	v := n
	for _, u := range units {
		v /= 1024
		if v < 1024 {
			return fmt.Sprintf("%.2f %s", v, u)
		}
	}
	return fmt.Sprintf("%.2f EiB", v/1024)
}

type histBucket struct {
	label string
	val   float64
	count int
}

func labelOf(v float64, unit string) string {
	return fmt.Sprintf("%5.3f %s", v, unit)
}

func buildHistogram(d *dist, unit string) []histBucket {
	if d.n() == 0 {
		b := []histBucket{}
		for i := 0; i < 11; i++ {
			b = append(b, histBucket{label: labelOf(math.NaN(), unit), val: math.NaN()})
		}
		return b
	}
	mn := d.min()
	mx := d.max()
	span := mx - mn
	step := span / 10
	out := make([]histBucket, 0, 11)
	for i := 0; i < 11; i++ {
		var bound float64
		if i == 10 {
			bound = mx
		} else {
			bound = mn + step*float64(i)
		}
		out = append(out, histBucket{label: labelOf(bound, unit), val: bound})
	}
	counts := make([]int, 11)
	s := d.sortVals()
	for _, v := range s {
		var idx int
		if span == 0 {
			idx = 0
		} else {
			r := (v - mn) / span * 10
			idx = int(math.Floor(r))
			if idx < 0 {
				idx = 0
			}
			if idx > 10 {
				idx = 10
			}
		}
		counts[idx]++
	}
	for i := range out {
		out[i].count = counts[i]
	}
	return out
}

func renderHistogram(b []histBucket, sb *strings.Builder) {
	maxCount := 0
	for _, h := range b {
		if h.count > maxCount {
			maxCount = h.count
		}
	}
	countWidth := len(fmt.Sprintf("%d", maxCount)) + 3
	labelWidth := 0
	for _, h := range b {
		if len(h.label) > labelWidth {
			labelWidth = len(h.label)
		}
	}
	labelWidth += 2
	for _, h := range b {
		bar := ""
		if maxCount > 0 && h.count > 0 {
			w := int(float64(h.count) / float64(maxCount) * 32)
			bar = strings.Repeat("\u25a0", w)
		}
		cnt := fmt.Sprintf("[%d]", h.count)
		if len(cnt) < countWidth {
			cnt += strings.Repeat(" ", countWidth-len(cnt))
		}
		lab := h.label
		if len(lab) < labelWidth {
			lab = strings.Repeat(" ", labelWidth-len(lab)) + lab
		}
		fmt.Fprintf(sb, "%s %s|%s\n", lab, cnt, bar)
	}
}

