	totalReq := s.success + s.errCount + s.deadlineAborts
	fmt.Fprintf(&sb, "Summary:\n")
	fmt.Fprintf(&sb, "  Success rate:\t%.2f%%\n", s.successRate()*100)
	fmt.Fprintf(&sb, "  Total:\t%s\n", formatTime(s.total, unit))
	fmt.Fprintf(&sb, "  Slowest:\t%s\n", formatTime(s.latency.max(), unit))
	fmt.Fprintf(&sb, "  Fastest:\t%s\n", formatTime(s.latency.min(), unit))
	fmt.Fprintf(&sb, "  Average:\t%s\n", formatTime(s.latency.mean(), unit))
	fmt.Fprintf(&sb, "  Requests/sec:\t%.4f\n", float64(totalReq)/s.total)
