	if s.success == 0 {
		fmt.Fprintf(&sb, "  Size/request:\tNaN\n")
	} else {
		fmt.Fprintf(&sb, "  Size/request:\t%s\n", formatBytes(float64(s.totalData)/float64(s.success)))
	}
	fmt.Fprintf(&sb, "  Size/sec:\t%s\n", formatBytes(float64(s.totalData)/s.total))
	fmt.Fprintf(&sb, "\n")
	fmt.Fprintf(&sb, "Response time histogram:\n")
	hb := buildHistogram(&s.latency, unit)
	renderHistogram(hb, &sb)
	fmt.Fprintf(&sb, "\n")
	renderDistribution(&s.latency, unit, "Response time distribution", &sb)
	if c.statsSuccessBreakdown {
		fmt.Fprintf(&sb, "\n")
		fmt.Fprintf(&sb, "Response time histogram (2xx only):\n")
		h2 := buildHistogram(&s.latency2xx, unit)
		renderHistogram(h2, &sb)
		fmt.Fprintf(&sb, "\n")
		renderDistribution(&s.latency2xx, unit, "Response time distribution (2xx only)", &sb)
		fmt.Fprintf(&sb, "\n")
		fmt.Fprintf(&sb, "Response time histogram (4xx + 5xx only):\n")
		h4 := buildHistogram(&s.latencyNot2xx, unit)
		renderHistogram(h4, &sb)
		fmt.Fprintf(&sb, "\n")
		renderDistribution(&s.latencyNot2xx, unit, "Response time distribution (4xx + 5xx only)", &sb)
	}
	fmt.Fprintf(&sb, "\n")
	fmt.Fprintf(&sb, "Details (average, fastest, slowest):\n")
	for _, r := range detailRows(s) {
		fmt.Fprintf(&sb, "  %s:\t%s, %s, %s\n", r.name, formatTime(r.average, unit), formatTime(r.fastest, unit), formatTime(r.slowest, unit))
	}
	fmt.Fprintf(&sb, "\n")
	fmt.Fprintf(&sb, "Status code distribution:\n")
