	fmt.Fprintf(&sb, "    \"successRate\": %s,\n", jsonVal(s.successRate()))
	fmt.Fprintf(&sb, "    \"total\": %s,\n", fmtFJSON(s.total))
	sr := jsonVal(s.latency.max())
	if math.IsInf(s.latency.max(), -1) {
		sr = "null"
	}
	fmt.Fprintf(&sb, "    \"slowest\": %s,\n", sr)
	fr := jsonVal(s.latency.min())
	if math.IsInf(s.latency.min(), 1) {
		fr = "null"
	}
	fmt.Fprintf(&sb, "    \"fastest\": %s,\n", fr)
	fmt.Fprintf(&sb, "    \"average\": %s,\n", jsonVal(s.latency.mean()))
	fmt.Fprintf(&sb, "    \"requestsPerSec\": %s,\n", fmtFJSON(float64(totalReq)/s.total))
	fmt.Fprintf(&sb, "    \"totalData\": %d,\n", s.totalData)
	if s.success == 0 {
		sb.WriteString("    \"sizePerRequest\": null,\n")
	} else {
		fmt.Fprintf(&sb, "    \"sizePerRequest\": %s,\n", fmtFJSON(float64(s.totalData)/float64(s.success)))
	}
	fmt.Fprintf(&sb, "    \"sizePerSec\": %s\n", fmtFJSON(float64(s.totalData)/s.total))
	sb.WriteString("  },\n")
	sb.WriteString("  \"responseTimeHistogram\": " + strings.ReplaceAll(jsonHist(&s.latency, c.timeUnit), "\n", "\n") + ",\n")
	sb.WriteString("  \"latencyPercentiles\": " + jsonPercentiles(&s.latency) + ",\n")
	if c.statsSuccessBreakdown {
		sb.WriteString("  \"responseTimeHistogramSuccessful\": " + jsonHist(&s.latency2xx, c.timeUnit) + ",\n")
		sb.WriteString("  \"latencyPercentilesSuccessful\": " + jsonPercentiles(&s.latency2xx) + ",\n")
		sb.WriteString("  \"responseTimeHistogramNotSuccessful\": " + jsonHist(&s.latencyNot2xx, c.timeUnit) + ",\n")
		sb.WriteString("  \"latencyPercentilesNotSuccessful\": " + jsonPercentiles(&s.latencyNot2xx) + ",\n")
	}
	// rps
	rps := s.rpsSeries()
	sb.WriteString("  \"rps\": {\n")
	m := rps.mean()
	if rps.n() == 0 {
		sb.WriteString("    \"mean\": null,\n")
		sb.WriteString("    \"stddev\": null,\n")
		sb.WriteString("    \"max\": null,\n")
		sb.WriteString("    \"min\": null,\n")
	} else {
		fmt.Fprintf(&sb, "    \"mean\": %s,\n", fmtFJSON(m))
		sd := rps.stddev()
		if math.IsNaN(sd) {
			sb.WriteString("    \"stddev\": null,\n")
		} else {
			fmt.Fprintf(&sb, "    \"stddev\": %s,\n", fmtFJSON(sd))
		}
		fmt.Fprintf(&sb, "    \"max\": %s,\n", fmtFJSON(rps.max()))
		fmt.Fprintf(&sb, "    \"min\": %s,\n", fmtFJSON(rps.min()))
	}
	sb.WriteString("    \"percentiles\": " + jsonPercentiles(&rps) + "\n")
	sb.WriteString("  },\n")
	// details
	sb.WriteString("  \"details\": {\n")
	sb.WriteString("    \"DNSDialup\": " + strings.Replace(jsonDetail(&s.dnsDial), "\n", "\n", -1) + ",\n")
	sb.WriteString("    \"DNSLookup\": " + jsonDetail(&s.dns) + "\n")
	sb.WriteString("  },\n")
	// status codes
	sb.WriteString("  \"statusCodeDistribution\": {")
	codes := sortedCodes(s)
	if len(codes) == 0 {
		sb.WriteString("}")
	} else {
		sb.WriteString("\n")
		for i, code := range codes {
			fmt.Fprintf(&sb, "    \"%d\": %d", code, s.statusCodes[code])
			if i < len(codes)-1 {
				sb.WriteString(",")
			}
			sb.WriteString("\n")
		}
		sb.WriteString("  }")
	}
	sb.WriteString(",\n")
	// errors
	sb.WriteString("  \"errorDistribution\": {")
	errs := sortedErrors(s)
	if len(errs) == 0 {
		sb.WriteString("}")
	} else {
		sb.WriteString("\n")
		for i, e := range errs {
			fmt.Fprintf(&sb, "    %q: %d", e, s.errDist[e])
			if i < len(errs)-1 {
				sb.WriteString(",")
			}
			sb.WriteString("\n")
		}
		sb.WriteString("  }")
	}
	sb.WriteString("\n}")
	return sb.String()
}

func csvReport(s *stats) string {
	var sb strings.Builder
	sb.WriteString("request-start,DNS,DNS+dialup,Response-delay,request-duration,bytes,status\n")
