package main

import (
	"bufio"
	"crypto/tls"
	"fmt"
	"net"
	"os"
	"regexp"
	"strconv"
	"strings"
	"sync"
	"time"
)

type connState struct {
	cfg   *config
	cl    *client
	c     net.Conn
	bw    *bufio.Writer
	br    *bufio.Reader
	tls   bool
}

func (cs *connState) close() {
	if cs.c != nil {
		cs.c.Close()
		cs.c = nil
	}
}

type workItem struct {
	target  *target
	method  string
	headers [][2]string
	body    []byte
}

type runner struct {
	cfg    *config
	client *client
	st     *stats
	mu     sync.Mutex
	startT time.Time
	// scheduling
	muQ     sync.Mutex
	nextT   float64
	schedI  uint64
	qps     float64
	// request sources
	urlGen     *urlGen
	urlList    []*target
	urlFromFile bool
	body       *bodySource
	form       []byte
	formBoundary string
	// counters
	totalSent uint64
	nRequests uint64
	useN      bool
	deadline  time.Time
	useDeadline bool
	waitOngoing bool
}

func (r *runner) elapsed() float64 { return time.Since(r.startT).Seconds() }

// acquire paces the send
func (r *runner) acquire() (float64, float64) {
	if r.qps <= 0 {
		return r.elapsed(), 0
	}
	r.muQ.Lock()
	now := r.elapsed()
	var sched float64
	if r.cfg.latencyCorrection {
		sched = float64(r.schedI) / r.qps
		r.schedI++
	} else {
		t := now
		if r.nextT > t {
			t = r.nextT
		}
		sched = t
		r.nextT = t + 1.0/r.qps
	}
	r.muQ.Unlock()
	for {
		now = r.elapsed()
		if now >= sched {
			break
		}
		d := time.Duration((sched - now) * float64(time.Second))
		if d > 20*time.Millisecond {
			d = 20 * time.Millisecond
		}
		if d < 100*time.Microsecond {
			d = 100 * time.Microsecond
		}
		time.Sleep(d)
	}
	return r.elapsed(), sched
}

func (r *runner) burstAcquire() float64 {
	// burst scheduling handled by burst scheduler goroutine
	return r.elapsed()
}

func (r *runner) nextURL() *target {
	if r.urlFromFile {
		i := int(randUint64() % uint64(len(r.urlList)))
		return r.urlList[i]
	}
	return r.urlList[0]
}

func (r *runner) genURL() *target {
	if r.urlGen != nil {
		s := r.urlGen.gen()
		t, err := makeTarget(s)
		if err != nil {
			return r.urlList[0]
		}
		return t
	}
	return r.nextURL()
}

var errDeadline = "aborted due to deadline"

func (r *runner) doRequest(cs *connState, widx int) *record {
	var item *target
	var body []byte
	var hdrs [][2]string
	var method string
	rec := &record{}
	if r.burstActive {
		<-r.burstChan
	}
	start, sched := r.acquire()
	rec.start = start
	if sched > 0 && r.cfg.latencyCorrection && start > sched+1e-9 {
		rec.startLC = sched
	}
	method = r.cfg.method
	if r.urlGen != nil {
		item = r.genURL()
	} else if r.urlFromFile {
		item = r.genURL()
	} else {
		item = r.urlList[0]
	}
	body = r.body.next()
	if r.formBoundary != "" {
		body = r.form
	}
	hostHeader := r.cfg.host
	if hostHeader == "" {
		hostHeader = item.hostPort()
		if (item.scheme == "http" && item.port == "80") || (item.scheme == "https" && item.port == "443") {
			hostHeader = item.host
		}
	}
	if c2, p2, ok := pickConnectTo(r.cfg.connectTo, item.host, item.port); ok {
		_ = c2
		_ = p2
		hostHeader = item.hostPort()
		if (item.scheme == "http" && item.port == "80") || (item.scheme == "https" && item.port == "443") {
			hostHeader = item.host
		}
	}
	hdrs = buildHeaders(r.cfg, hostHeader, body, r.formBoundary)
	// proxy headers
	if r.cfg.proxy != "" {
		for _, h := range r.cfg.proxyHeaders {
			ci := strings.Index(h, ":")
			if ci < 0 {
				continue
			}
			hdrs = append(hdrs, [2]string{strings.ToLower(strings.TrimSpace(h[:ci])), strings.TrimSpace(h[ci+1:])})
		}
	}
	if r.cfg.disableKeepalive {
		hdrs = append(hdrs, [2]string{"connection", "close"})
	}
