cd /workspace/src && cat > run.go <<'GOEOF'
package main

import (
	"bufio"
	"crypto/tls"
	"fmt"
	"net"
	"os"
	"regexp"
	"strconv"
	"strings"
	"sync"
	"time"
)

type connState struct {
	cfg   *config
	cl    *client
	c     net.Conn
	bw    *bufio.Writer
	br    *bufio.Reader
	tls   bool
}

func (cs *connState) close() {
	if cs.c != nil {
		cs.c.Close()
		cs.c = nil
	}
}

type workItem struct {
	target  *target
	method  string
	headers [][2]string
	body    []byte
}

type runner struct {
	cfg    *config
	client *client
	st     *stats
	mu     sync.Mutex
	startT time.Time
	// scheduling
	muQ     sync.Mutex
	nextT   float64
	schedI  uint64
	qps     float64
	// request sources
	urlGen     *urlGen
	urlList    []*target
	urlFromFile bool
	body       *bodySource
	form       []byte
	formBoundary string
	// counters
	totalSent uint64
	nRequests uint64
	useN      bool
	deadline  time.Time
	useDeadline bool
	waitOngoing bool
}

func (r *runner) elapsed() float64 { return time.Since(r.startT).Seconds() }

// acquire paces the send
func (r *runner) acquire() (float64, float64) {
	if r.qps <= 0 {
		return r.elapsed(), 0
	}
	r.muQ.Lock()
	now := r.elapsed()
	var sched float64
	if r.cfg.latencyCorrection {
		sched = float64(r.schedI) / r.qps
		r.schedI++
	} else {
		t := now
		if r.nextT > t {
			t = r.nextT
		}
		sched = t
		r.nextT = t + 1.0/r.qps
	}
	r.muQ.Unlock()
	for {
		now = r.elapsed()
		if now >= sched {
			break
		}
		d := time.Duration((sched - now) * float64(time.Second))
		if d > 20*time.Millisecond {
			d = 20 * time.Millisecond
		}
		if d < 100*time.Microsecond {
			d = 100 * time.Microsecond
		}
		time.Sleep(d)
	}
	return r.elapsed(), sched
}

func (r *runner) burstAcquire() float64 {
	// burst scheduling handled by burst scheduler goroutine
	return r.elapsed()
}

func (r *runner) nextURL() *target {
	if r.urlFromFile {
		i := int(randUint64() % uint64(len(r.urlList)))
		return r.urlList[i]
	}
	return r.urlList[0]
}

func (r *runner) genURL() *target {
	if r.urlGen != nil {
		s := r.urlGen.gen()
		t, err := makeTarget(s)
		if err != nil {
			return r.urlList[0]
		}
		return t
	}
	return r.nextURL()
}

var errDeadline = "aborted due to deadline"

func (r *runner) doRequest(cs *connState, widx int) *record {
	var item *target
	var body []byte
	var hdrs [][2]string
	var method string
	rec := &record{}
	if r.burstActive {
		<-r.burstChan
	}
	start, sched := r.acquire()
	rec.start = start
	if sched > 0 && r.cfg.latencyCorrection && start > sched+1e-9 {
		rec.startLC = sched
	}
	method = r.cfg.method
	if r.urlGen != nil {
		item = r.genURL()
	} else if r.urlFromFile {
		item = r.genURL()
	} else {
		item = r.urlList[0]
	}
	body = r.body.next()
	if r.formBoundary != "" {
		body = r.form
	}
	hostHeader := r.cfg.host
	if hostHeader == "" {
		hostHeader = item.hostPort()
		if (item.scheme == "http" && item.port == "80") || (item.scheme == "https" && item.port == "443") {
			hostHeader = item.host
		}
	}
	if c2, p2, ok := pickConnectTo(r.cfg.connectTo, item.host, item.port); ok {
		_ = c2
		_ = p2
		hostHeader = item.hostPort()
		if (item.scheme == "http" && item.port == "80") || (item.scheme == "https" && item.port == "443") {
			hostHeader = item.host
		}
	}
	hdrs = buildHeaders(r.cfg, hostHeader, body, r.formBoundary)
	// proxy headers
	if r.cfg.proxy != "" {
		for _, h := range r.cfg.proxyHeaders {
			ci := strings.Index(h, ":")
			if ci < 0 {
				continue
			}
			hdrs = append(hdrs, [2]string{strings.ToLower(strings.TrimSpace(h[:ci])), strings.TrimSpace(h[ci+1:])})
		}
	}
	if r.cfg.disableKeepalive {
		hdrs = append(hdrs, [2]string{"connection", "close"})
	}
	uri := item.path
	if r.cfg.proxy != "" {
		uri = item.abs
	}

	var dns, dnsDial float64
	needNew := cs.c == nil || r.cfg.disableKeepalive || cs.host != item.host || cs.port != item.port || cs.scheme != item.scheme
	if needNew {
		cs.close()
		d0 := time.Now()
		ips, d, err := r.client.resolve(item)
		if err != nil {
			rec.err = fmt.Sprintf("no records found for Query { name: Name(\"%s.\"), query_type: AAAA, query_class: IN }", item.host)
			if !strings.Contains(rec.err, "Query") {
				rec.err = err.Error()
			}
			rec.start = start
			rec.end = r.elapsed()
			rec.duration = r.elapsed() - start
			return rec
		}
		dnsDur := d
		if r.client.cachedDNS {
			dnsDur = 0
		}
		// dial
		addr := ""
		if r.cfg.proxy != "" {
			pt, err := makeTarget(r.cfg.proxy)
			if err != nil {
				rec.err = err.Error()
				return rec
			}
			addr = net.JoinHostPort(pt.host, pt.port)
		} else {
			c2h, c2p, ok := pickConnectTo(r.cfg.connectTo, item.host, item.port)
			if ok {
				addr = net.JoinHostPort(c2h, c2p)
			} else {
				addr = net.JoinHostPort(ips[0].String(), item.port)
			}
		}
		var conn net.Conn
		var dialErr error
		dialStart := time.Now()
		for attempt := 0; attempt < 1; attempt++ {
			if r.cfg.unixSocket != "" {
				conn, dialErr = net.DialTimeout("unix", r.cfg.unixSocket, r.cfg.connectTimeout)
			} else {
				conn, dialErr = net.DialTimeout("tcp", addr, r.cfg.connectTimeout)
			}
			if dialErr == nil {
				break
			}
			break
		}
		dialDur := time.Since(dialStart)
		if dialErr != nil {
			rec.err = cleanErr(dialErr)
			rec.end = r.elapsed()
			rec.duration = r.elapsed() - start
			return rec
		}
		if item.scheme == "https" {
			tc, err2 := tlsConfig(r.client, item.host)
			if err2 != nil {
				rec.err = cleanErr(err2)
				rec.end = r.elapsed()
				rec.duration = r.elapsed() - start
				conn.Close()
				return rec
			}
			tconn := tls.Client(conn)
			tconn.SetDeadline(time.Time{})
			if err := tconn.Handshake(); err != nil {
				rec.err = cleanErr(err)
				rec.end = r.elapsed()
				rec.duration = r.elapsed() - start
				conn.Close()
				return rec
			}
			handshakeDur := time.Since(dialStart)
			dialDur = handshakeDur
			conn = tconn
		}
		dns = dnsDur.Seconds()
		dnsDial = (dialStart.Sub(d0) + dialDur).Seconds()
		if !r.client.cachedDNS {
			dnsDial = dns + dialDur.Seconds()
		}
		cs.c = conn
		cs.bw = bufio.NewWriter(conn)
		cs.br = bufio.NewReaderSize(conn, 64*1024)
		cs.host = item.host
		cs.port = item.port
		cs.scheme = item.scheme
	}
	// set deadlines
	if !r.useDeadline || r.cfg.waitOngoing {
		if r.cfg.timeout > 0 {
			cs.c.SetDeadline(time.Now().Add(r.cfg.timeout))
		} else {
			cs.c.SetDeadline(time.Time{})
		}
	} else {
		cs.c.SetDeadline(r.deadline)
	}
	respDelay := 0.0
	redirected := false
	status := 0
	totalBytes := uint64(0)
	curTarget := item
	curURI := uri
	var lastResp *respInfo
	for hop := 0; ; hop++ {
		if hop > int(r.cfg.redirect) {
			break
		}
		resp, err := sendRequest(cs.bw, cs.br, method, curURI, hostHeader, hdrs, body, r.cfg.httpVersion)
		if err != nil {
			if isTimeoutErr(err) && r.useDeadline && !r.cfg.waitOngoing {
				rec.err = errDeadline
				rec.isDeadline = true
			} else if isTimeoutErr(err) && r.cfg.timeout > 0 {
				rec.err = "timeout"
			} else {
				rec.err = cleanErr(err)
			}
			cs.close()
			rec.end = r.elapsed()
			rec.duration = r.elapsed() - start
			return rec
		}
		if hop == 0 {
			respDelay = r.elapsed() - start
		}
		lastResp = resp
		status = resp.status
		// redirect?
		if isRedirect(resp.status) && hop < int(r.cfg.redirect) {
			loc, ok := headerGet(resp.headers, "location")
			if ok {
				nt, err := resolveRedirect(curTarget, loc)
				if err == nil {
					redirected = true
					curTarget = nt
					curURI = nt.path
					hostHeader = nt.hostPort()
					if (nt.scheme == "http" && nt.port == "80") || (nt.scheme == "https" && nt.port == "443") {
						hostHeader = nt.host
					}
					if nt.scheme == "http" && resp.status == 303 {
						method = "GET"
						body = nil
					} else if resp.status == 301 || resp.status == 302 || resp.status == 303 {
						method = "GET"
						body = nil
					}
					hdrs = buildHeaders(r.cfg, hostHeader, body, r.formBoundary)
					if r.cfg.disableKeepalive {
						hdrs = append(hdrs, [2]string{"connection", "close"})
					}
					needNew2 := cs.c == nil || cs.host != nt.host || cs.port != nt.port || cs.scheme != nt.scheme
					if needNew2 {
						cs.close()
						ips, _, err := r.client.resolve(nt)
						if err != nil {
							rec.err = cleanErr(err)
							rec.end = r.elapsed()
							rec.duration = r.elapsed() - start
							return rec
						}
						conn, dialErr := dialAddr(r.client, ips[0], nt.port, r.cfg.unixSocket, r.cfg.connectTimeout)
						if dialErr != nil {
							rec.err = cleanErr(dialErr)
							rec.end = r.elapsed()
							rec.duration = r.elapsed() - start
							return rec
						}
						if nt.scheme == "https" {
							tc, err2 := tlsConfig(r.client, nt.host)
							if err2 != nil {
								rec.err = cleanErr(err2)
								rec.end = r.elapsed()
								rec.duration = r.elapsed() - start
								conn.Close()
								return rec
							}
							tconn := tls.Client(conn)
							if e := tconn.Handshake(); e != nil {
								rec.err = cleanErr(e)
								rec.end = r.elapsed()
								rec.duration = r.elapsed() - start
								conn.Close()
								return rec
							}
							conn = tconn
						}
						cs.c = conn
						cs.bw = bufio.NewWriter(conn)
						cs.br = bufio.NewReaderSize(conn, 64*1024)
						cs.host = nt.host
						cs.port = nt.port
						cs.scheme = nt.scheme
					}
					continue
				}
			}
		}
		totalBytes = uint64(len(lastResp.body))
		break
	}
	rec.respDelay = respDelay
	if redirected {
		rec.respDelay = 0
	}
	rec.redirected = redirected
	rec.duration = r.elapsed() - start
	rec.bytes = totalBytes
	rec.status = status
	rec.url = curTarget.path
	rec.end = r.elapsed()
	rec.latencyOK = is2xx(status)
	return rec
}

var _ = regexp.MustCompile

func isRedirect(code int) bool {
	return code == 301 || code == 302 || code == 303 || code == 307 || code == 308
}

func resolveRedirect(t *target, loc string) (*target, error) {
	u, err := makeTarget(absURL(t, loc))
	if err != nil {
		return nil, err
	}
	return u, nil
}

func absURL(t *target, loc string) string {
	if strings.HasPrefix(loc, "http://") || strings.HasPrefix(loc, "https://") {
		return loc
	}
	if strings.HasPrefix(loc, "//") {
		return t.scheme + ":" + loc
	}
	if strings.HasPrefix(loc, "/") {
		return t.scheme + "://" + t.hostPort() + loc
	}
	// relative: strip last path segment
	base := t.raw
	if i := strings.LastIndex(base, "/"); i >= 0 {
		base = base[:i+1]
	}
	return base + loc
}

func isTimeoutErr(err error) bool {
	if ne, ok := err.(net.Error); ok {
		return ne.Timeout()
	}
	s := err.Error()
	return strings.Contains(s, "i/o timeout") || strings.Contains(s, "timeout")
}

var errMap = map[string]string{
	"connection refused": "Connection refused (os error 111)",
	"no route to host":   "Network is unreachable (os error 101)",
	"network is unreachable": "Network is unreachable (os error 101)",
	"connection reset by peer": "Connection reset by peer (os error 104)",
	"broken pipe":            "Broken pipe (os error 32)",
	"no such file or directory": "No such file or directory (os error 2)",
	"i/o timeout":            "timeout",
	"connection timed out":   "Connection timed out (os error 110)",
}

func cleanErr(err error) string {
	s := err.Error()
	l := strings.ToLower(s)
	for k, v := range errMap {
		if strings.Contains(l, k) {
			return v
		}
	}
	if strings.Contains(s, "tls:") || strings.Contains(s, "x509") {
		return tlsErrMsg(s)
	}
	return s
}

func tlsErrMsg(s string) string {
	return s
}

var burstActive bool
var burstChan chan struct{}

func runLoad(c *config) *stats {
	seedRand()
	st := newStats()
	// resolve urls
	var urlList []*target
	var ug *urlGen
	var err error
	if c.urlsFromFile {
		data, err2 := os.ReadFile(c.urlArgOrEmpty())
		if err2 != nil {
			fatalErr(cleanErr(err2))
		}
		for _, line := range strings.Split(strings.TrimRight(string(data), "\n"), "\n") {
			line = strings.TrimSpace(line)
			if line == "" {
				continue
			}
			t, e := makeTarget(line)
			if e != nil {
				fatalErr(e.Error())
			}
			urlList = append(urlList, t)
		}
		if len(urlList) == 0 {
			fatalErr("no urls")
		}
	} else if c.randRegexURL {
		pat := c.urlArgOrEmpty()
		ug, err = newURLGen(pat, c.maxRepeat)
		if err != nil {
			fatalErr(err.Error())
		}
		t, e := makeTarget(ug.gen())
		if e != nil {
			fatalErr(e.Error() + ", generated url: " + pat)
		}
		urlList = append(urlList, t)
	} else {
		t, e := makeTarget(c.urlArgOrEmpty())
		if e != nil {
			fatalErr(e.Error())
		}
		urlList = append(urlList, t)
	}
	if c.dumpURLs > 0 {
		if c.randRegexURL {
			for i := uint64(0); i < c.dumpURLs; i++ {
				s := ug.gen()
				fmt.Println(s)
			}
		} else {
			for i := uint64(0); i < c.dumpURLs; i++ {
				fmt.Println(urlList[0].raw)
			}
		}
		os.Exit(0)
	}
	body, err := newBodySource(c)
	if err != nil {
		fatalErr(cleanErr(err))
	}
	var formBody []byte
	var formBoundary string
	if len(c.form) > 0 {
		formBody, formBoundary, err = buildMultipart(c)
		if err != nil {
			fatalErr(cleanErr(err))
		}
	}
	r := &runner{
		cfg:       c,
		st:        st,
		client:    &client{cfg: c},
		urlList:   urlList,
		urlGen:    ug,
		urlFromFile: c.urlsFromFile,
		body:      body,
		form:      formBody,
		formBoundary: formBoundary,
		nRequests: c.nRequests,
		useN:      !c.useDuration,
		deadline:  time.Now().Add(c.duration),
		useDeadline: c.useDuration,
		waitOngoing: c.waitOngoing,
		qps:       c.qps,
		burstChan: make(chan struct{}, 4096),
	}
	if c.burstDelay > 0 && c.qps <= 0 {
		burstActive = true
	}
	// pre lookup
	if !c.noPreLookup {
		_, d, err := r.client.resolve(urlList[0])
		if err != nil {
			fatalErr("proto error: " + err.Error())
		}
		r.client.cachedDNS = true
		_ = d
	}
	r.startT = time.Now()
	if c.dbURL != "" {
		fmt.Printf("Storing results to %s\n", c.dbURL)
	}
	// burst scheduler
	stopBurst := make(chan struct{})
	if burstActive {
		go func() {
			ticker := time.NewTicker(c.burstDelay)
			defer ticker.Stop()
			for {
				select {
				case <-stopBurst:
					return
				case <-ticker.C:
					n := int(c.burstRate)
					if n < 1 {
						n = 1
					}
					for i := 0; i < n; i++ {
						select {
						case r.burstChan <- struct{}{}:
						default:
						}
					}
				}
			}
		}()
	}
	var wg sync.WaitGroup
	nw := c.nConnections
	if nw < 0 {
		nw = 0
	}
	for i := 0; i < nw; i++ {
		wg.Add(1)
		go func(widx int) {
			defer wg.Done()
			cs := &connState{cfg: c, cl: r.client}
			defer cs.close()
			for {
				if r.useN {
					if r.claimRequest() == false {
						return
					}
				} else {
					if time.Now().After(r.deadline) {
						return
					}
				}
				rec := r.doRequest(cs, widx)
				r.mu.Lock()
				st.add(rec)
				r.mu.Unlock()
			}
		}(i)
	}
	if r.useN {
		go func() {
			for {
				time.Sleep(50 * time.Millisecond)
				r.mu.Lock()
				done := r.completed >= r.nRequests
				r.mu.Unlock()
				if done {
					return
				}
			}
		}()
	} else {
		go func() {
			time.Sleep(c.duration)
			<-make(chan struct{})
		}()
	}
	// wait for completion
	done := make(chan struct{})
	go func() {
		wg.Wait()
		close(done)
	}()
	if r.useN {
		<-done
	} else {
		if c.waitOngoing {
			<-done
		} else {
			<-done
		}
	}
	if burstActive {
		close(stopBurst)
	}
	r.mu.Lock()
	defer r.mu.Unlock()
	st.total = time.Since(r.startT).Seconds()
	return st
}

func (c *config) urlArgOrEmpty() string {
	return c.urlArg
}

func (r *runner) claimRequest() bool {
	r.muQ.Lock()
	defer r.muQ.Unlock()
	if r.claimed >= r.nRequests {
		return false
	}
	r.claimed++
	return true
}
