func (r *runner) acquire() (float64, float64) {
	if r.qps <= 0 {
		return r.elapsed(), 0
	}
	r.muQ.Lock()
	now := r.elapsed()
	var sched float64
	if r.cfg.latencyCorrection {
		sched = float64(r.schedI) / r.qps
		r.schedI++
	} else {
		t := now
		if r.nextT > t {
