				}
			}
		}()
	}
	var wg sync.WaitGroup
	nw := c.nConnections
	for i := 0; i < nw; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			cs := &connState{cfg: c, cl: r.cl}
			defer cs.close()
			for {
				if r.useN {
					if !r.claim() {
						return
					}
				} else if time.Now().After(r.deadline) {
					return
				}
				if r.useDeadline && !r.waitOngoing {
					if time.Now().After(r.deadline) {
						if r.useN {
							r.claim()
						}
						return
					}
				}
				rec := r.doRequest(cs)
				r.mu.Lock()
				st.add(rec)
				r.mu.Unlock()
			}
		}()
	}
	done := make(chan struct{})
	go func() {
		wg.Wait()
		close(done)
	}()
	if r.useN {
		<-done
	} else {
		<-time.After(time.Until(r.deadline))
	}
	if r.burstOn {
		close(stopBurst)
	}
	r.mu.Lock()
	defer r.mu.Unlock()
	st.total = time.Since(r.startT).Seconds()
	return st
}

