package main

import (
	"bufio"
	"crypto/tls"
	"fmt"
	"net"
	"os"
	"strconv"
	"strings"
	"sync"
	"time"
)

type connState struct {
	cfg    *config
	cl     *client
	c      net.Conn
	bw     *bufio.Writer
	br     *bufio.Reader
	host   string
	port   string
	scheme string
}

func (cs *connState) close() {
	if cs.c != nil {
		cs.c.Close()
		cs.c = nil
	}
}

type runner struct {
	cfg    *config
	cl     *client
	st     *stats
	mu     sync.Mutex
	startT time.Time
	// scheduling
	muQ    sync.Mutex
	nextT  float64
	schedI uint64
	claimed uint64
	qps    float64
	urlList []*target
	urlGen *urlGen
	body   *bodySource
	form        []byte
	formBoundary string
	nRequests   uint64
	useN        bool
	deadline    time.Time
	useDeadline bool
	waitOngoing bool
	burstChan   chan struct{}
	burstOn     bool
}

func (r *runner) elapsed() float64 { return time.Since(r.startT).Seconds() }

func (r *runner) claim() bool {
	if !r.useN {
		return true
	}
	r.muQ.Lock()
	defer r.muQ.Unlock()
	if r.claimed >= r.nRequests {
		return false
	}
	r.claimed++
	return true
}

func (r *runner) acquire() (float64, float64) {
	if r.qps <= 0 {
		return r.elapsed(), 0
	}
	r.muQ.Lock()
	now := r.elapsed()
	var sched float64
	if r.cfg.latencyCorrection {
		sched = float64(r.schedI) / r.qps
		r.schedI++
	} else {
		t := now
		if r.nextT > t {
			t = r.nextT
		}
		sched = t
		r.nextT = t + 1.0/r.qps
	}
	r.muQ.Unlock()
	for {
		now = r.elapsed()
		if now >= sched {
			break
		}
		d := time.Duration((sched - now) * float64(time.Second))
		if d > 20*time.Millisecond {
			d = 20 * time.Millisecond
		}
		if d < 50*time.Microsecond {
			d = 50 * time.Microsecond
		}
		time.Sleep(d)
	}
	return r.elapsed(), sched
}

func (r *runner) pickTarget() *target {
	if r.urlGen != nil {
		s := r.urlGen.gen()
		t, err := makeTarget(s)
		if err != nil {
			return r.urlList[0]
		}
		return t
	}
	if len(r.urlList) > 1 {
		i := int(randUint64() % uint64(len(r.urlList)))
		return r.urlList[i]
	}
	return r.urlList[0]
}

func hostHeaderFor(t *target, cfg *config) string {
	if cfg.host != "" {
		return cfg.host
	}
	if (t.scheme == "http" && t.port == "80") || (t.scheme == "https" && t.port == "443") {
		return t.host
	}
	return t.host + ":" + t.port
}

func (r *runner) dial(cs *connState, t *target) (dns float64, dnsDial float64, err error) {
	cs.close()
	d0 := time.Now()
	var ips []net.IP
	var d time.Duration
	var e error
	host := t.host
	port := t.port
	if r.cfg.proxy != "" {
		pt, pe := makeTarget(r.cfg.proxy)
		if pe != nil {
			return 0, 0, pe
		}
		host = pt.host
		port = pt.port
	} else if c2h, c2p, ok := pickConnectTo(r.cfg.connectTo, t.host, t.port); ok {
		host = c2h
		port = c2p
	}
	ips, d, e = r.cl.resolveHost(host, t)
	if e != nil {
		return 0, 0, e
	}
	dnsDur := d
	dialStart := time.Now()
	var conn net.Conn
	if r.cfg.unixSocket != "" {
		conn, e = net.DialTimeout("unix", r.cfg.unixSocket, r.cfg.connectTimeout)
	} else {
		conn, e = net.DialTimeout("tcp", net.JoinHostPort(ips[0].String(), port), r.cfg.connectTimeout)
	}
	if e != nil {
		return dnsDur.Seconds(), 0, e
	}
	dialDur := time.Since(dialStart)
	if t.scheme == "https" && r.cfg.unixSocket == "" {
		tc, e2 := tlsConfig(r.cl, t.host)
		if e2 != nil {
			conn.Close()
			return dnsDur.Seconds(), 0, e2
		}
		tconn := tls.Client(conn)
		tconn.SetDeadline(time.Time{})
		if e2 = tconn.Handshake(); e2 != nil {
			conn.Close()
			return dnsDur.Seconds(), 0, e2
		}
		dialDur = time.Since(dialStart)
		conn = tconn
	}
	dnsDial = (dialStart.Sub(d0) + dialDur).Seconds()
	if r.cl.cachedDNS {
		dns = 0
		dnsDial = dialDur.Seconds()
	} else {
		dns = dnsDur.Seconds()
		dnsDial = dns + dialDur.Seconds()
	}
	cs.c = conn
	cs.bw = bufio.NewWriter(conn)
	cs.br = bufio.NewReaderSize(conn, 64*1024)
	cs.host = t.host
	cs.port = t.port
	cs.scheme = t.scheme
	return dns, dnsDial, nil
}

func (r *runner) doRequest(cs *connState) *record {
	rec := &record{}
	if r.burstOn {
		<-r.burstChan
	}
	start, sched := r.acquire()
	rec.start = start
	if r.cfg.latencyCorrection && sched > 0 && start > sched+1e-9 {
		rec.startLC = sched
	}
	item := r.pickTarget()
	body := r.body.next()
	if r.formBoundary != "" {
		body = r.form
	}
	method := r.cfg.method
	hostHeader := hostHeaderFor(item, r.cfg)
	hdrs := buildHeaders(r.cfg, hostHeader, body, r.formBoundary)
	if r.cfg.proxy != "" {
		for _, h := range r.cfg.proxyHeaders {
			ci := strings.Index(h, ":")
			if ci < 0 {
				continue
			}
			hdrs = append(hdrs, [2]string{strings.ToLower(strings.TrimSpace(h[:ci])), strings.TrimSpace(h[ci+1:])})
		}
	}
	if r.cfg.disableKeepalive {
		hdrs = append(hdrs, [2]string{"connection", "close"})
	}
	uri := item.path
	if r.cfg.proxy != "" {
		uri = item.abs
	}
	var dns, dnsDial float64
	if cs.c == nil || r.cfg.disableKeepalive || cs.host != item.host || cs.port != item.port || cs.scheme != item.scheme {
		d, dd, err := r.dial(cs, item)
		if err != nil {
			rec.err = cleanErr(err)
			rec.end = r.elapsed()
			rec.duration = rec.end - start
			return rec
		}
		dns, dnsDial = d, dd
	}
	rec.dns = dns
	rec.dnsDial = dnsDial
	// deadlines
	if r.useDeadline && !r.waitOngoing {
		cs.c.SetDeadline(r.deadline)
	} else if r.cfg.timeout > 0 {
		cs.c.SetDeadline(time.Now().Add(r.cfg.timeout))
	} else {
		cs.c.SetDeadline(time.Time{})
	}
	respDelay := 0.0
	redirected := false
	status := 0
	totalBytes := uint64(0)
	curTarget := item
	curURI := uri
	curHost := hostHeader
	curMethod := method
	curBody := body
	curHdrs := hdrs
	maxRedirect := int(r.cfg.redirect)
	for hop := 0; hop <= maxRedirect; hop++ {
		resp, err := sendRequest(cs.bw, cs.br, curMethod, curURI, curHost, curHdrs, curBody, r.cfg.httpVersion)
		if err != nil {
			if isTimeoutErr(err) {
				if r.useDeadline && !r.waitOngoing {
					rec.err = errDeadline
					rec.isDeadline = true
				} else if r.cfg.timeout > 0 {
					rec.err = "timeout"
				} else {
					rec.err = cleanErr(err)
				}
			} else {
				rec.err = cleanErr(err)
			}
			cs.close()
			rec.end = r.elapsed()
			rec.duration = rec.end - start
			return rec
		}
		if hop == 0 {
			respDelay = r.elapsed() - start
		}
		status = resp.status
		if isRedirect(status) && hop < maxRedirect {
			if loc, ok := headerGet(resp.headers, "location"); ok {
				nt, e := resolveRedirect(curTarget, loc)
				if e == nil {
					redirected = true
					curTarget = nt
					curURI = nt.path
					curHost = hostHeaderFor(nt, r.cfg)
					if status == 301 || status == 302 || status == 303 {
						curMethod = "GET"
						curBody = nil
					}
					curHdrs = buildHeaders(r.cfg, curHost, curBody, r.formBoundary)
					if r.cfg.disableKeepalive {
						curHdrs = append(curHdrs, [2]string{"connection", "close"})
					}
					if cs.c == nil || cs.host != nt.host || cs.port != nt.port || cs.scheme != nt.scheme {
						_, _, e2 := r.dial(cs, nt)
						if e2 != nil {
							rec.err = cleanErr(e2)
							cs.close()
							rec.end = r.elapsed()
							rec.duration = rec.end - start
							return rec
						}
					}
					if r.useDeadline && !r.waitOngoing {
						cs.c.SetDeadline(r.deadline)
					} else if r.cfg.timeout > 0 {
						cs.c.SetDeadline(time.Now().Add(r.cfg.timeout))
					}
					continue
				}
			}
		}
		totalBytes = uint64(len(resp.body))
		break
	}
	rec.respDelay = respDelay
	if redirected {
		rec.respDelay = 0
	}
	rec.redirected = redirected
	rec.duration = r.elapsed() - start
	rec.bytes = totalBytes
	rec.status = status
	rec.url = curTarget.path
	rec.end = r.elapsed()
	return rec
}

func isRedirect(code int) bool {
	return code == 301 || code == 302 || code == 303 || code == 307 || code == 308
}

func resolveRedirect(t *target, loc string) (*target, error) {
	return makeTarget(absURL(t, loc))
}

func absURL(t *target, loc string) string {
	if strings.HasPrefix(loc, "http://") || strings.HasPrefix(loc, "https://") {
		return loc
	}
	if strings.HasPrefix(loc, "//") {
		return t.scheme + ":" + loc
	}
	if strings.HasPrefix(loc, "/") {
		return t.scheme + "://" + t.hostPort() + loc
	}
	base := t.raw
	if i := strings.LastIndex(base, "/"); i >= 0 {
		base = base[:i+1]
	}
	return base + loc
}

func isTimeoutErr(err error) bool {
	if ne, ok := err.(net.Error); ok {
		return ne.Timeout()
	}
	s := err.Error()
	return strings.Contains(s, "i/o timeout") || strings.Contains(s, "timeout")
}

var errMap = [][2]string{
	{"connection refused", "Connection refused (os error 111)"},
	{"network is unreachable", "Network is unreachable (os error 101)"},
	{"no route to host", "Network is unreachable (os error 101)"},
	{"connection reset by peer", "Connection reset by peer (os error 104)"},
	{"broken pipe", "Broken pipe (os error 32)"},
	{"no such file or directory", "No such file or directory (os error 2)"},
	{"connection timed out", "Connection timed out (os error 110)"},
	{"too many open files", "Too many open files (os error 24)"},
	{"permission denied", "Permission denied (os error 13)"},
	{"unknown host", "Temporary failure in name resolution (os error 11)"},
}

func cleanErr(err error) string {
	s := err.Error()
	l := strings.ToLower(s)
	for _, kv := range errMap {
		if strings.Contains(l, kv[0]) {
			return kv[1]
		}
	}
	if strings.Contains(s, "server closed") {
		return s
	}
	if strings.Contains(l, "certificate") || strings.Contains(l, "x509") || strings.Contains(l, "tls:") {
		return tlsErrMsg(s)
	}
	return s
}

func tlsErrMsg(s string) string {
	// mimic rustls style errors for common cases
	if strings.Contains(s, "certificate is valid for") || strings.Contains(s, "IP SAN") {
		return "invalid peer certificate: Other(OtherError(CaUsedAsEndEntity))"
	}
	return s
}

func runLoad(c *config) *stats {
	seedRand()
	st := newStats()
	var urlList []*target
	var ug *urlGen
	var err error
	if c.urlsFromFile {
		data, e2 := os.ReadFile(c.urlArg)
		if e2 != nil {
			fatalErr(cleanErr(e2))
		}
		for _, line := range strings.Split(strings.TrimRight(string(data), "\n"), "\n") {
			line = strings.TrimSpace(line)
			if line == "" {
				continue
			}
			t, e := makeTarget(line)
			if e != nil {
				fatalErr(e.Error())
			}
			urlList = append(urlList, t)
		}
		if len(urlList) == 0 {
			fatalErr("no urls")
		}
	} else if c.randRegexURL {
		ug, err = newURLGen(c.urlArg, c.maxRepeat)
		if err != nil {
			fatalErr(err.Error())
		}
		t, e := makeTarget(ug.gen())
		if e != nil {
			fatalErr(e.Error() + ", generated url: " + c.urlArg)
		}
		urlList = append(urlList, t)
	} else {
		t, e := makeTarget(c.urlArg)
		if e != nil {
			fatalErr(e.Error())
		}
		urlList = append(urlList, t)
	}
	if c.dumpURLs > 0 {
		for i := uint64(0); i < c.dumpURLs; i++ {
			if c.randRegexURL {
				fmt.Println(ug.gen())
			} else {
				fmt.Println(urlList[0].raw)
			}
		}
		os.Exit(0)
	}
	body, err := newBodySource(c)
	if err != nil {
		fatalErr(cleanErr(err))
	}
	var formBody []byte
	var formBoundary string
	if len(c.form) > 0 {
		formBody, formBoundary, err = buildMultipart(c)
		if err != nil {
			fatalErr(cleanErr(err))
		}
	}
	r := &runner{
		cfg:         c,
		cl:          &client{cfg: c},
		st:          st,
		urlList:     urlList,
		urlGen:      ug,
		body:        body,
		form:        formBody,
		formBoundary: formBoundary,
		nRequests:   c.nRequests,
		useN:        !c.useDuration,
		deadline:    time.Now().Add(c.duration),
		useDeadline: c.useDuration,
		waitOngoing: c.waitOngoing,
		qps:         c.qps,
		burstChan:   make(chan struct{}, 1<<20),
		burstOn:     c.burstDelay > 0 && c.qps <= 0,
	}
	// pre-lookup
	if !c.noPreLookup {
		if _, _, e := r.cl.resolveHost(urlList[0].host, urlList[0]); e != nil {
			fatalErr("proto error: " + e.Error())
		}
		r.cl.cachedDNS = true
	}
	r.startT = time.Now()
	if c.dbURL != "" {
		fmt.Printf("Storing results to %s\n", c.dbURL)
	}
	stopBurst := make(chan struct{})
	if r.burstOn {
		go func() {
			ticker := time.NewTicker(c.burstDelay)
			defer ticker.Stop()
			for {
				select {
				case <-stopBurst:
					return
				case <-ticker.C:
					n := int(c.burstRate)
					if n < 1 {
						n = 1
					}
					for i := 0; i < n; i++ {
						select {
						case r.burstChan <- struct{}{}:
						default:
						}
					}
				}
			}
		}()
	}
	var wg sync.WaitGroup
	nw := c.nConnections
	for i := 0; i < nw; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			cs := &connState{cfg: c, cl: r.cl}
			defer cs.close()
			for {
				if r.useN {
					if !r.claim() {
						return
					}
				} else if time.Now().After(r.deadline) {
					return
				}
				if r.useDeadline && !r.waitOngoing {
					if time.Now().After(r.deadline) {
						if r.useN {
							r.claim()
						}
						return
					}
				}
				rec := r.doRequest(cs)
				r.mu.Lock()
				st.add(rec)
				r.mu.Unlock()
			}
		}()
	}
	done := make(chan struct{})
	go func() {
		wg.Wait()
		close(done)
	}()
	if r.useN {
		<-done
	} else {
		<-time.After(time.Until(r.deadline))
	}
	if r.burstOn {
		close(stopBurst)
	}
	r.mu.Lock()
	defer r.mu.Unlock()
	st.total = time.Since(r.startT).Seconds()
	return st
}

var _ = strconv.Itoa
GOEOF
echo ok

