var wsNode = &classNode{ranges: [][2]rune{{'\t', '\r'}, {' ', ' '}}}
var wordNode = &classNode{ranges: [][2]rune{{'0', '9'}, {'A', 'Z'}, {'_', '_'}, {'a', 'z'}}}
