type parser struct {
	s   string
	i   int
	mr  int
	src string
}

func newURLGen(pattern string, maxRepeat uint32) (*urlGen, error) {
	escaped := strings.ReplaceAll(pattern, ".", "\\.")
	p := &parser{s: escaped, mr: int(maxRepeat), src: escaped}
	n, err := p.parseAlt()
	if err != nil {
		return nil, err
	}
	if p.i < len(p.s) {
		return nil, p.errAt(p.i, "unexpected close parenthesis")
	}
	return &urlGen{root: n}, nil
}

func (p *parser) errAt(pos int, msg string) error {
	caret := pos
	lines := "Error: regex parse error:\n    " + p.src + "\n    " + strings.Repeat(" ", carret) + "^\nerror: " + msg
	return errors.New(lines)
}

func (p *parser) parseAlt() (node, error) {
	var alts []node
	cur := &catNode{}
	for p.i < len(p.s) {
		c := p.s[p.i]
		if c == '|' {
			p.i++
			alts = append(alts, cur)
			cur = &catNode{}
			continue
		}
		if c == ')' {
			break
		}
		n, err := p.parseAtom()
		if err != nil {
			return nil, err
		}
		n, err = p.parseQuant(n)
		if err != nil {
			return nil, err
		}
		cur.kids = append(cur.kids, n)
	}
	if len(alts) > 0 {
		alts = append(alts, cur)
		return &altNode{alts: alts}, nil
	}
	return cur, nil
}

func (p *parser) parseAtom() (node, error) {
	if p.i >= len(p.s) {
		return &litNode{}, nil
	}
	c := p.s[p.i]
	switch c {
	case '(':
		p.i++
		var nonCap bool
		if strings.HasPrefix(p.s[p.i:], "?:") {
			nonCap = true
			p.i += 2
		}
		_ = nonCap
		n, err := p.parseAlt()
		if err != nil {
			return nil, err
		}
		if p.i >= len(p.s) || p.s[p.i] != ')' {
			return nil, p.errAt(p.i, "unclosed group")
		}
		p.i++
		return n, nil
	case '[':
		return p.parseClass()
	case '\\':
		p.i++
		if p.i >= len(p.s) {
			return nil, p.errAt(p.i, "incomplete escape sequence, reached end of pattern prematurely")
		}
		e := p.s[p.i]
		p.i++
		switch e {
		case 'd':
			return digitNode, nil
		case 'D':
			return &classNode{ranges: [][2]rune{{'0', '9'}}, negate: true}, nil
		case 'w':
			return wordNode, nil
		case 'W':
			return &classNode{ranges: [][2]rune{{'0', '9'}, {'A', 'Z'}, {'_', '_'}, {'a', 'z'}}, negate: true}, nil
		case 's':
			return wsNode, nil
		case 'S':
			return &classNode{ranges: [][2]rune{{'\t', '\r'}, {' ', ' '}}, negate: true}, nil
		case 'n':
			return &litNode{s: "\n"}, nil
		case 'r':
			return &litNode{s: "\r"}, nil
		case 't':
			return &litNode{s: "\t"}, nil
		default:
			return &litNode{s: string(e)}, nil
		}
	case '^', '$':
		p.i++
		return &litNode{s: ""}, nil
	default:
		p.i++
		return &litNode{s: string(c)}, nil
	}
}

func (p *parser) parseQuant(n node) (node, error) {
	for p.i < len(p.s) {
		c := p.s[p.i]
		switch c {
		case '*':
			p.i++
			return &repNode{kid: n, lo: 0, hi: p.mr}, nil
		case '+':
			p.i++
			return &repNode{kid: n, lo: 1, hi: 1 + p.mr}, nil
		case '?':
			p.i++
			return &repNode{kid: n, lo: 0, hi: 1}, nil
		case '{':
			j := p.i + 1
			num1 := ""
			for j < len(p.s) && p.s[j] >= '0' && p.s[j] <= '9' {
				num1 += string(p.s[j])
				j++
			}
			if j < len(p.s) && p.s[j] == '}' {
				hi := atoi(num1)
				p.i = j + 1
				return &repNode{kid: n, lo: hi, hi: hi}, nil
			}
			if j < len(p.s) && p.s[j] == ',' {
				j++
				num2 := ""
				for j < len(p.s) && p.s[j] >= '0' && p.s[j] <= '9' {
					num2 += string(p.s[j])
					j++
				}
				if j < len(p.s) && p.s[j] == '}' {
					lo := atoi(num1)
					hi := lo + p.mr
					if num2 != "" {
						hi = atoi(num2)
					}
					p.i = j + 1
					return &repNode{kid: n, lo: lo, hi: hi}, nil
				}
			}
			// literal '{'
			p.i++
			return &litNode{s: "{"}, nil
		default:
			return n, nil
		}
	}
	return n, nil
}

func atoi(s string) int {
	n := 0
	for _, c := range s {
		n = n*10 + int(c-'0')
	}
	return n
}

func (p *parser) parseClass() (node, error) {
	start := p.i
	p.i++ // [
	negate := false
	if p.i < len(p.s) && p.s[p.i] == '^' {
		negate = true
		p.i++
	}
	cl := &classNode{negate: negate}
	first := true
	for {
		if p.i >= len(p.s) {
			return nil, p.errAt(start, "unclosed character class")
		}
		c := p.s[p.i]
		if c == ']' && !first {
			p.i++
			break
		}
		first = false
		// posix class
		if c == '[' && strings.HasPrefix(p.s[p.i:], "[:") {
			j := strings.Index(p.s[p.i:], ":]")
			if j > 0 {
				name := p.s[p.i+2 : p.i+j]
				p.i += j + 2
				switch name {
				case "alpha":
					cl.ranges = append(cl.ranges, [2]rune{'A', 'Z'}, [2]rune{'a', 'z'})
				case "digit":
					cl.ranges = append(cl.ranges, [2]rune{'0', '9'})
				case "alnum":
					cl.ranges = append(cl.ranges, [2]rune{'0', '9'}, [2]rune{'A', 'Z'}, [2]rune{'a', 'z'})
				case "upper":
					cl.ranges = append(cl.ranges, [2]rune{'A', 'Z'})
				case "lower":
					cl.ranges = append(cl.ranges, [2]rune{'a', 'z'})
				case "space":
					cl.ranges = append(cl.ranges, [2]rune{'\t', '\r'}, [2]rune{' ', ' '})
				case "punct":
					cl.ranges = append(cl.ranges, [2]rune{'!', '/'}, [2]rune{':', '@'}, [2]rune{'[', '`'}, [2]rune{'{', '~'})
				case "print":
					cl.ranges = append(cl.ranges, [2]rune{' ', '~'})
				case "xdigit":
					cl.ranges = append(cl.ranges, [2]rune{'0', '9'}, [2]rune{'A', 'F'}, [2]rune{'a', 'f'})
				default:
					return nil, p.errAt(start, "unknown POSIX character class")
				}
				continue
			}
		}
		if c == '\\' {
			p.i++
			if p.i >= len(p.s) {
				return nil, p.errAt(start, "unclosed character class")
			}
			e := p.s[p.i]
			p.i++
			switch e {
			case 'd':
				cl.ranges = append(cl.ranges, [2]rune{'0', '9'})
			case 'w':
				cl.ranges = append(cl.ranges, [2]rune{'0', '9'}, [2]rune{'A', 'Z'}, [2]rune{'_', '_'}, [2]rune{'a', 'z'})
			case 's':
				cl.ranges = append(cl.ranges, [2]rune{'\t', '\r'}, [2]rune{' ', ' '})
			case 'n':
				cl.ranges = append(cl.ranges, [2]rune{'\n', '\n'})
			case 't':
				cl.ranges = append(cl.ranges, [2]rune{'\t', '\t'})
			default:
				cl.ranges = append(cl.ranges, [2]rune{rune(e), rune(e)})
			}
			continue
		}
		p.i++
		lo := rune(c)
		hi := lo
		if p.i+1 < len(p.s) && p.s[p.i] == '-' && p.s[p.i+1] != ']' {
			p.i++
			hi = rune(p.s[p.i])
			p.i++
			if hi < lo {
				return nil, p.errAt(start, "invalid character class range, the start must be <= the end")
			}
		}
		cl.ranges = append(cl.ranges, [2]rune{lo, hi})
	}
	return cl, nil
}

type urlGen struct {
	root node
}

func (u *urlGen) gen() string {
	return u.root.gen()
}

