package main

import (
	"errors"
	"fmt"
	"strings"
)

// Simple regex-based URL generator (rand_regex compatible subset).
type node interface {
	gen() string
	maxLen() int
}

type litNode struct{ s string }

func (l *litNode) gen() string    { return l.s }
func (l *litNode) maxLen() int    { return len(l.s) }

type classNode struct {
	ranges [][2]rune
	negate bool
}

func (c *classNode) gen() string {
	for tries := 0; tries < 20; tries++ {
		var ch rune
		if c.negate {
			for {
				ch = rune(32 + randUint64()%95)
				ok := true
				for _, r := range c.ranges {
					if ch >= r[0] && ch <= r[1] {
						ok = false
						break
					}
				}
				if ok {
					break
				}
			}
		} else {
			total := 0
			for _, r := range c.ranges {
				total += int(r[1]-r[0]) + 1
			}
			if total == 0 {
				return ""
			}
			pick := randUint64() % uint64(total)
			for _, r := range c.ranges {
				n := int(r[1]-r[0]) + 1
				if uint64(n) > pick {
					ch = r[0] + rune(pick)
					break
				}
				pick -= uint64(n)
			}
		}
		return string(ch)
	}
	return ""
}
func (c *classNode) maxLen() int { return 1 }

type catNode struct{ kids []node }

func (c *catNode) gen() string {
	var sb strings.Builder
	for _, k := range c.kids {
		sb.WriteString(k.gen())
	}
	return sb.String()
}
func (c *catNode) maxLen() int {
	n := 0
	for _, k := range c.kids {
		n += k.maxLen()
	}
	return n
}

type altNode struct{ alts []node }

func (a *altNode) gen() string {
	i := randUint64() % uint64(len(a.alts))
	return a.alts[i].gen()
}
func (a *altNode) maxLen() int {
	m := 0
	for _, k := range a.alts {
		if k.maxLen() > m {
			m = k.maxLen()
		}
	}
	return m
}

type repNode struct {
	kid   node
	lo    int
	hi    int
}

func (r *repNode) gen() string {
	n := r.lo
	if r.hi > r.lo {
		n += int(randUint64() % uint64(r.hi-r.lo+1))
	}
	var sb strings.Builder
	for i := 0; i < n; i++ {
		sb.WriteString(r.kid.gen())
	}
	return sb.String()
}
func (r *repNode) maxLen() int { return r.hi * r.kid.maxLen() }

// unicode decimal digit (Nd) approximations
var ndRanges = [][2]rune{
	{0x0030, 0x0039}, {0x0660, 0x0669}, {0x06F0, 0x06F9}, {0x07C0, 0x07C9},
	{0x0966, 0x096F}, {0x09E6, 0x09EF}, {0x0A66, 0x0A6F}, {0x0AE6, 0x0AEF},
	{0x0B66, 0x0B6F}, {0x0BE6, 0x0BEF}, {0x0C66, 0x0C6F}, {0x0CE6, 0x0CEF},
	{0x0D66, 0x0D6F}, {0x0E50, 0x0E59}, {0x0ED0, 0x0ED9}, {0x0F20, 0x0F29},
	{0x1040, 0x1049}, {0x17E0, 0x17E9}, {0x1810, 0x1819}, {0x1E50, 0x1E59},
	{0x2070, 0x2079}, {0x2080, 0x2089}, {0x2488, 0x2493}, {0x2776, 0x277F},
	{0x3021, 0x3029}, {0x4E00}, {0xFF10, 0xFF19},
	{0x1D7CE, 0x1D7FF},
	{0x11A50, 0x11A59}, {0x114D0, 0x114D9},
}

type unicodeClass struct {
	ranges [][2]rune
}

func (u *unicodeClass) gen() string {
	var total uint64
	for _, r := range u.ranges {
		total += uint64(r[1]-r[0]) + 1
	}
	if total == 0 {
		return ""
	}
	pick := randUint64() % total
	for _, r := range u.ranges {
		n := uint64(r[1]-r[0]) + 1
		if n > pick {
			return string(r[0] + rune(pick))
		}
		pick -= n
	}
	return ""
}
func (u *unicodeClass) maxLen() int { return 1 }

var wsNode = &classNode{ranges: [][2]rune{{'\t', '\r'}, {' ', ' '}}}
var wordNode = &classNode{ranges: [][2]rune{{'0', '9'}, {'A', 'Z'}, {'_', '_'}, {'a', 'z'}}}
var digitNode = &unicodeClass{ranges: ndRanges}

type parser struct {
	s   string
	i   int
	mr  int
	src string
}

func newURLGen(pattern string, maxRepeat uint32) (*urlGen, error) {
	escaped := strings.ReplaceAll(pattern, ".", "\\.")
	p := &parser{s: escaped, mr: int(maxRepeat), src: escaped}
	n, err := p.parseAlt()
	if err != nil {
		return nil, err
	}
	if p.i < len(p.s) {
		return nil, p.errAt(p.i, "unexpected close parenthesis")
	}
	return &urlGen{root: n}, nil
}

func (p *parser) errAt(pos int, msg string) error {
	caret := pos
	lines := "Error: regex parse error:\n    " + p.src + "\n    " + strings.Repeat(" ", carret) + "^\nerror: " + msg
	return errors.New(lines)
}

func (p *parser) parseAlt() (node, error) {
	var alts []node
	cur := &catNode{}
	for p.i < len(p.s) {
		c := p.s[p.i]
		if c == '|' {
			p.i++
			alts = append(alts, cur)
			cur = &catNode{}
			continue
		}
		if c == ')' {
			break
		}
		n, err := p.parseAtom()
		if err != nil {
			return nil, err
		}
		n, err = p.parseQuant(n)
		if err != nil {
			return nil, err
		}
		cur.kids = append(cur.kids, n)
	}
	if len(alts) > 0 {
		alts = append(alts, cur)
		return &altNode{alts: alts}, nil
	}
	return cur, nil
}

func (p *parser) parseAtom() (node, error) {
	if p.i >= len(p.s) {
		return &litNode{}, nil
	}
	c := p.s[p.i]
	switch c {
	case '(':
		p.i++
		var nonCap bool
		if strings.HasPrefix(p.s[p.i:], "?:") {
			nonCap = true
			p.i += 2
		}
		_ = nonCap
		n, err := p.parseAlt()
		if err != nil {
			return nil, err
		}
		if p.i >= len(p.s) || p.s[p.i] != ')' {
			return nil, p.errAt(p.i, "unclosed group")
		}
		p.i++
		return n, nil
	case '[':
		return p.parseClass()
	case '\\':
		p.i++
		if p.i >= len(p.s) {
			return nil, p.errAt(p.i, "incomplete escape sequence, reached end of pattern prematurely")
		}
		e := p.s[p.i]
		p.i++
		switch e {
		case 'd':
			return digitNode, nil
		case 'D':
			return &classNode{ranges: [][2]rune{{'0', '9'}}, negate: true}, nil
		case 'w':
			return wordNode, nil
		case 'W':
			return &classNode{ranges: [][2]rune{{'0', '9'}, {'A', 'Z'}, {'_', '_'}, {'a', 'z'}}, negate: true}, nil
		case 's':
			return wsNode, nil
		case 'S':
			return &classNode{ranges: [][2]rune{{'\t', '\r'}, {' ', ' '}}, negate: true}, nil
		case 'n':
			return &litNode{s: "\n"}, nil
		case 'r':
			return &litNode{s: "\r"}, nil
		case 't':
			return &litNode{s: "\t"}, nil
		default:
			return &litNode{s: string(e)}, nil
		}
	case '^', '$':
		p.i++
		return &litNode{s: ""}, nil
	default:
		p.i++
		return &litNode{s: string(c)}, nil
	}
}

func (p *parser) parseQuant(n node) (node, error) {
	for p.i < len(p.s) {
		c := p.s[p.i]
		switch c {
		case '*':
			p.i++
			return &repNode{kid: n, lo: 0, hi: p.mr}, nil
		case '+':
			p.i++
			return &repNode{kid: n, lo: 1, hi: 1 + p.mr}, nil
		case '?':
			p.i++
			return &repNode{kid: n, lo: 0, hi: 1}, nil
		case '{':
			j := p.i + 1
			num1 := ""
			for j < len(p.s) && p.s[j] >= '0' && p.s[j] <= '9' {
				num1 += string(p.s[j])
				j++
			}
			if j < len(p.s) && p.s[j] == '}' {
				hi := atoi(num1)
				p.i = j + 1
				return &repNode{kid: n, lo: hi, hi: hi}, nil
			}
			if j < len(p.s) && p.s[j] == ',' {
				j++
				num2 := ""
				for j < len(p.s) && p.s[j] >= '0' && p.s[j] <= '9' {
					num2 += string(p.s[j])
					j++
				}
				if j < len(p.s) && p.s[j] == '}' {
					lo := atoi(num1)
					hi := lo + p.mr
					if num2 != "" {
						hi = atoi(num2)
					}
					p.i = j + 1
					return &repNode{kid: n, lo: lo, hi: hi}, nil
				}
			}
			// literal '{'
			p.i++
			return &litNode{s: "{"}, nil
		default:
			return n, nil
		}
	}
	return n, nil
}

func atoi(s string) int {
	n := 0
	for _, c := range s {
		n = n*10 + int(c-'0')
	}
	return n
}

func (p *parser) parseClass() (node, error) {
	start := p.i
	p.i++ // [
	negate := false
	if p.i < len(p.s) && p.s[p.i] == '^' {
		negate = true
		p.i++
	}
	cl := &classNode{negate: negate}
	first := true
	for {
		if p.i >= len(p.s) {
			return nil, p.errAt(start, "unclosed character class")
		}
		c := p.s[p.i]
		if c == ']' && !first {
			p.i++
			break
		}
		first = false
		// posix class
		if c == '[' && strings.HasPrefix(p.s[p.i:], "[:") {
			j := strings.Index(p.s[p.i:], ":]")
			if j > 0 {
				name := p.s[p.i+2 : p.i+j]
				p.i += j + 2
				switch name {
				case "alpha":
					cl.ranges = append(cl.ranges, [2]rune{'A', 'Z'}, [2]rune{'a', 'z'})
				case "digit":
					cl.ranges = append(cl.ranges, [2]rune{'0', '9'})
				case "alnum":
					cl.ranges = append(cl.ranges, [2]rune{'0', '9'}, [2]rune{'A', 'Z'}, [2]rune{'a', 'z'})
				case "upper":
					cl.ranges = append(cl.ranges, [2]rune{'A', 'Z'})
				case "lower":
					cl.ranges = append(cl.ranges, [2]rune{'a', 'z'})
				case "space":
					cl.ranges = append(cl.ranges, [2]rune{'\t', '\r'}, [2]rune{' ', ' '})
				case "punct":
					cl.ranges = append(cl.ranges, [2]rune{'!', '/'}, [2]rune{':', '@'}, [2]rune{'[', '`'}, [2]rune{'{', '~'})
				case "print":
					cl.ranges = append(cl.ranges, [2]rune{' ', '~'})
				case "xdigit":
					cl.ranges = append(cl.ranges, [2]rune{'0', '9'}, [2]rune{'A', 'F'}, [2]rune{'a', 'f'})
				default:
					return nil, p.errAt(start, "unknown POSIX character class")
				}
				continue
			}
		}
		if c == '\\' {
			p.i++
			if p.i >= len(p.s) {
				return nil, p.errAt(start, "unclosed character class")
			}
			e := p.s[p.i]
			p.i++
			switch e {
			case 'd':
				cl.ranges = append(cl.ranges, [2]rune{'0', '9'})
			case 'w':
				cl.ranges = append(cl.ranges, [2]rune{'0', '9'}, [2]rune{'A', 'Z'}, [2]rune{'_', '_'}, [2]rune{'a', 'z'})
			case 's':
				cl.ranges = append(cl.ranges, [2]rune{'\t', '\r'}, [2]rune{' ', ' '})
			case 'n':
				cl.ranges = append(cl.ranges, [2]rune{'\n', '\n'})
			case 't':
				cl.ranges = append(cl.ranges, [2]rune{'\t', '\t'})
			default:
				cl.ranges = append(cl.ranges, [2]rune{rune(e), rune(e)})
			}
			continue
		}
		p.i++
		lo := rune(c)
		hi := lo
		if p.i+1 < len(p.s) && p.s[p.i] == '-' && p.s[p.i+1] != ']' {
			p.i++
			hi = rune(p.s[p.i])
			p.i++
			if hi < lo {
				return nil, p.errAt(start, "invalid character class range, the start must be <= the end")
			}
		}
		cl.ranges = append(cl.ranges, [2]rune{lo, hi})
	}
	return cl, nil
}

type urlGen struct {
	root node
}

func (u *urlGen) gen() string {
	return u.root.gen()
}

