package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"
	"time"
)

func main() {
	p := parseArgs(os.Args[1:])
	if p.has("V") {
		printVersion()
		return
	}
	if p.has("h") {
		printHelp()
		return
	}
	c := buildConfig(p)
	c.urlArg = p.url
	seedRand()
	// custom validations
	if c.http2 && strings.Contains(strings.Join(p.all("http-version"), ""), "") && p.has("http-version") {
		fatalErr("--http2 and --http-version are exclusive")
	}
	if c.proxyHTTP2 && p.has("proxy-http-version") {
		fatalErr("--http2 and --http-version are exclusive")
	}
	if c.awsSigv4 != "" && c.basicAuth == "" {
		fatalErr("AWS credentials (--auth) required when using --aws-sigv4")
	}
	if c.cert != "" && c.key == "" {
		// handled in parse (requires)
	}
	if v, ok := p.one("http-version"); ok {
		if !validVersion(v) {
			fatalErr("Unknown HTTP version. Valid versions are 0.9, 1.0, 1.1, 2, 3")
		}
	}
	if v, ok := p.one("proxy-http-version"); ok {
		if !validVersion(v) {
			fatalErr("Unknown HTTP version. Valid versions are 0.9, 1.0, 1.1, 2, 3")
		}
	}
	// output destination
	var out *os.File
	if c.output != "" {
		f, err := os.Create(c.output)
		if err != nil {
			fatalErr(cleanErr(err))
		}
		defer f.Close()
		out = f
	} else {
		out = os.Stdout
	}
	bw := bufio.NewWriter(out)
	defer bw.Flush()

	if c.debug {
		doDebug(c, bw)
		return
	}
	st := runLoad(c)
	if c.dbURL != "" {
		writeDB(c, st)
	}
	switch c.outputFormat {
	case "json":
		bw.WriteString(jsonReport(st, c) + "\n")
	case "csv":
		bw.WriteString(csvReport(st))
	case "quiet":
		// nothing
	default:
		bw.WriteString(textReport(st, c))
	}
	bw.Flush()
}

func validVersion(v string) bool {
	switch v {
	case "0.9", "1.0", "1.1", "2", "3":
		return true
	}
	return false
}

func doDebug(c *config, bw *bufio.Writer) {
	seedRand()
	var t *target
	var err error
	if c.urlsFromFile {
		data, e := os.ReadFile(c.urlArg)
		if e != nil {
			fatalErr(cleanErr(e))
		}
		lines := strings.Split(strings.TrimRight(string(data), "\n"), "\n")
		var ts []*target
		for _, l := range lines {
			l = strings.TrimSpace(l)
			if l == "" {
				continue
			}
			tt, e2 := makeTarget(l)
			if e2 != nil {
				fatalErr(e2.Error())
			}
			ts = append(ts, tt)
		}
		if len(ts) == 0 {
			fatalErr("no urls")
		}
		t = ts[int(randUint64())%len(ts)]
	} else if c.randRegexURL {
		ug, e := newURLGen(c.urlArg, c.maxRepeat)
		if e != nil {
			fatalErr(e.Error())
		}
		s := ug.gen()
		t, err = makeTarget(s)
		if err != nil {
			fatalErr(err.Error() + ", generated url: " + s)
		}
	} else {
		t, err = makeTarget(c.urlArg)
		if err != nil {
			fatalErr(err.Error())
		}
	}
	cl := &client{cfg: c}
	if !c.noPreLookup {
		if _, _, e := cl.resolveHost(t.host, t); e != nil {
			fatalErr("proto error: " + e.Error())
		}
		cl.cachedDNS = true
	}
	cs := &connState{cfg: c, cl: cl}
	if _, _, e := cl.dialConn(cs, t); e != nil {
		fatalErr("proto error: " + cleanErr(e))
	}
	body := []byte(nil)
	var formBoundary string
	bs, _ := newBodySource(c)
	body = bs.next()
	if len(c.form) > 0 {
		body, formBoundary, err = buildMultipart(c)
		if err != nil {
			fatalErr(cleanErr(err))
		}
	}
	hostHeader := hostHeaderFor(t, c)
	hdrs := buildHeaders(c, hostHeader, body, formBoundary)
	if c.proxy != "" {
		for _, h := range c.proxyHeaders {
			ci := strings.Index(h, ":")
			if ci < 0 {
				continue
			}
			hdrs = append(hdrs, [2]string{strings.ToLower(strings.TrimSpace(h[:ci])), strings.TrimSpace(h[ci+1:])})
		}
	}
	uri := t.path
	if c.proxy != "" {
		uri = t.abs
	}
	if c.timeout > 0 {
		cs.c.SetDeadline(time.Now().Add(c.timeout))
	}
	// dump request
	fmt.Fprintf(bw, "Request {\n")
	fmt.Fprintf(bw, "    method: %s,\n", c.method)
	fmt.Fprintf(bw, "    uri: %s,\n", uri)
	ver := "HTTP/1.1"
	switch c.httpVersion {
	case "0.9":
		ver = "HTTP/0.9"
	case "1.0":
		ver = "HTTP/1.0"
	case "2":
		ver = "HTTP/2.0"
	case "3":
		ver = "HTTP/3"
	}
	fmt.Fprintf(bw, "    version: %s,\n", ver)
	fmt.Fprintf(bw, "    headers: {\n")
	for _, h := range hdrs {
		fmt.Fprintf(bw, "        %q: %q,\n", h[0], h[1])
	}
	fmt.Fprintf(bw, "    },\n")
	if body == nil {
		fmt.Fprintf(bw, "    body: Full {\n        data: None,\n    },\n")
	} else {
		fmt.Fprintf(bw, "    body: Full {\n        data: Some(\n            b%s,\n        ),\n    },\n", rustBytes(body))
	}
	fmt.Fprintf(bw, "}\n")
	resp, err := sendRequest(cs.bw, cs.br, c.method, uri, hostHeader, hdrs, body, c.httpVersion)
	if err != nil {
		fmt.Fprintf(bw, "Error: %s\n", cleanErr(err))
		bw.Flush()
		os.Exit(1)
	}
	fmt.Fprintf(bw, "Response {\n")
	fmt.Fprintf(bw, "    status: %d,\n", resp.status)
	rv := "HTTP/1.1"
	if resp.version != "" {
		rv = resp.version
	}
	fmt.Fprintf(bw, "    version: %s,\n", rv)
	fmt.Fprintf(bw, "    headers: {\n")
	for _, h := range resp.headers {
		fmt.Fprintf(bw, "        %q: %q,\n", h[0], h[1])
	}
	fmt.Fprintf(bw, "    },\n")
	fmt.Fprintf(bw, "    body: b%s,\n", rustBytes(resp.body))
	fmt.Fprintf(bw, "}\n")
}

func rustBytes(b []byte) string {
	var sb strings.Builder
	sb.WriteString("\"")
	for i := 0; i < len(b); {
		c := b[i]
		if c < 0x80 {
			switch c {
			case '"':
				sb.WriteString("\\\"")
			case '\\':
				sb.WriteString("\\\\")
			case '\n':
				sb.WriteString("\\n")
			case '\r':
				sb.WriteString("\\r")
			case '\t':
				sb.WriteString("\\t")
			default:
				if c >= 0x20 && c < 0x7f {
					sb.WriteByte(c)
				} else {
					fmt.Fprintf(&sb, "\\x%02x", c)
				}
			}
			i++
			continue
		}
		// try utf8
		r, size := decodeRune(b[i:])
		if size > 0 {
			sb.WriteString(string(r))
			i += size
		} else {
			fmt.Fprintf(&sb, "\\x%02x", c)
			i++
		}
	}
	sb.WriteString("\"")
	return sb.String()
}

func decodeRune(b []byte) (rune int, size int) {
	n := len(b)
	if n == 0 {
		return 0, 0
	}
	c := b[0]
	var l int
	if c < 0x80 {
		return int(c), 1
	} else if c&0xE0 == 0xC0 {
		l = 2
	} else if c&0xF0 == 0xE0 {
		l = 3
	} else if c&0xF8 == 0xF0 {
		l = 4
	} else {
		return 0, 0
	}
	if n < l {
		return 0, 0
	}
	for i := 1; i < l; i++ {
		if b[i]&0xC0 != 0x80 {
			return 0, 0
		}
	}
	// decode
	var v rune = rune(c)
	switch l {
	case 2:
		v = rune(c & 0x1F)
	case 3:
		v = rune(c & 0x0F)
	case 4:
		v = rune(c & 0x07)
	}
