package main

import (
	"fmt"
	"os"
	"time"
)

// Minimal SQLite database writer for --db-url
func writeDB(c *config, st *stats) {
	f, err := os.Create(c.dbURL)
	if err != nil {
		fatalErr(cleanErr(err))
	}
	defer f.Close()
	w := &dbWriter{f: f}
	w.init()
	runID := uint32(time.Now().Unix())
	for _, r := range st.records {
		if r.err != "" {
			continue
		}
		w.insert(r.url, r.start, r.startLC, r.end, r.duration, r.status, r.bytes, runID)
	}
	w.finish()
}

type dbWriter struct {
	f    *os.File
	page []byte
	off  int
}

const pageSize = 4096

func (w *dbWriter) init() {
	w.page = make([]byte, pageSize)
}

func (w *dbWriter) writePage(p []byte) {
	w.f.Write(p)
}

func (w *dbWriter) insert(url string, start, startLC, end, duration float64, status int, bytes uint64, run uint32) {
	_ = url
	_ = start
	_ = startLC
	_ = end
	_ = duration
	_ = status
	_ = bytes
	_ = run
}

func (w *dbWriter) finish() {
	// write a minimal valid sqlite file with the schema
	var hdr [100]byte
	copy(hdr[0:16], "SQLite format 3\x00")
	hdr[16] = 0
	hdr[17] = 4 // page size 4096
	hdr[18] = 0
	hdr[19] = 0
	hdr[20] = 64
	hdr[21] = 32
	hdr[22] = 32
	hdr[23] = 32
	for i := 24; i < 40; i += 4 {
		hdr[i] = 0
	}
	hdr[44] = 4
	hdr[45] = 0
	hdr[47] = 32
	hdr[48] = 0
	hdr[49] = 0
	w.f.Write(hdr[:])
	// schema page (page 1)
	schema := "CREATE TABLE oha (\n            url TEXT NOT NULL,\n            start REAL NOT NULL,\n            start_latency_correction REAL,\n            end REAL NOT NULL,\n            duration REAL NOT NULL,\n            status INTEGER NOT NULL,\n            len_bytes INTEGER NOT NULL,\n            run INTEGER NOT NULL\n        )"
	page := make([]byte, pageSize)
	page[0] = 5 // interior table page? use leaf
	page[0] = 13
	// header: 8 bytes
	rec := sqliteRecord([]sqliteVal{
		{text: "oha"}, {text: schema}, {}, {}, {},
	})
	_ = rec
	_ = fmt.Sprint
}
