// Minimal SQLite file writer (enough for oha --db-url output).
type sqliteVal struct {
	isNull bool
	text   string
	real   float64
	int    int64
}

type sqliteWriter struct {
	f      *os.File
	page   []byte
	cellOff int
	off    int // offset within page where next cell is written (from end)
	rows   int
	pageNo int
}

const pgSize = 4096

func newSQLite(f *os.File) *sqliteWriter {
	return &sqliteWriter{f: f, pageNo: 0}
}

func (w *sqliteWriter) createTable(name, sql string) {
	// pages: 1 = sqlite_master leaf, 2.. = table leaf
	w.f.Truncate(0)
	w.page = make([]byte, pgSize)
	// page 1 header written at finish
	w.off = pgSize
	w.rows = 0
	// add the schema row
	w.addRow(sqliteRecord([]sqliteVal{
		{text: "table"}, {text: name}, {int: 2}, {text: sql},
	}))
	w.flushMaster()
}

func sqliteRecord(vals []sqliteVal) []byte {
	var body []byte
	var hdr []byte
	for _, v := range vals {
		if v.isNull {
			hdr = appendVarint(hdr, 0)
			continue
		}
		if v.text != "" {
			hdr = appendVarint(hdr, uint64(len(v.text)*2+13))
			body = append(body, v.text...)
			continue
		}
		if v.real != 0 || math.IsNaN(v.real) {
			hdr = appendVarint(hdr, 7)
			b := make([]byte, 8)
			binary.BigEndian.PutUint64(b, math.Float64bits(v.real))
			body = append(body, b...)
			continue
		}
		// integer
		i := v.int
		switch {
		case i == 0:
			hdr = appendVarint(hdr, 8)
		case i == 1:
			hdr = appendVarint(hdr, 9)
		case i >= -128 && i <= 127:
			hdr = appendVarint(hdr, 1)
			body = append(body, byte(i))
		case i >= -32768 && i <= 32767:
			hdr = appendVarint(hdr, 2)
			b := make([]byte, 2)
			binary.BigEndian.PutUint16(b, uint16(i))
			body = append(body, b...)
		case i >= -2147483648 && i <= 2147483647:
			hdr = appendVarint(hdr, 4)
			b := make([]byte, 4)
			binary.BigEndian.PutUint32(b, uint32(i))
			body = append(body, b...)
		default:
			hdr = appendVarint(hdr, 6)
			b := make([]byte, 8)
			binary.BigEndian.PutUint64(b, uint64(i))
			body = append(body, b...)
		}
	}
	hl := len(hdr)
	hdrSize := appendVarint(nil, uint64(hl))
	rec := append(append([]byte{}, hdrSize...), hdr...)
	rec = append(rec, body...)
	return rec
}

func appendVarint(b []byte, v uint64) []byte {
	if v <= 0x7f {
		return append(b, byte(v))
	}
	if v <= 0x3fff {
		return append(b, byte((v>>7)|0x80), byte(v&0x7f))
	}
	var tmp []byte
	for v > 0 {
		tmp = append([]byte{byte(v & 0x7f)}, tmp...)
		v >>= 7
	}
	for i := 0; i < len(tmp)-1; i++ {
		tmp[i] |= 0x80
	}
	return append(b, tmp...)
