func (w *sqliteWriter) addRow(rec []byte) {
	// leaf page cell: varint payload len, varint rowid, payload
	cell := appendVarint(nil, uint64(len(rec)))
	cell = append(cell, appendVarint(nil, uint64(w.rows+1))...)
	cell = append(cell, rec...)
	w.cellOff = pgSize - len(cell)
	copy(w.page[w.cellOff:], cell)
	w.off = w.cellOff
	w.rows++
}

func (w *sqliteWriter) flushMaster() {
	// page 1: btree leaf for sqlite_master
	p := make([]byte, pgSize)
	p[100] = 13 // leaf table
	binary.BigEndian.PutUint16(p[103:105], uint16(pgSize))
	binary.BigEndian.PutUint32(p[28:32], 0)
	binary.BigEndian.PutUint16(p[105:107], 0)
	binary.BigEndian.PutUint16(p[106:108], uint16(w.off))
	binary.BigEndian.PutUint16(p[103:105], uint16(w.off))
	n := w.rows
	binary.BigEndian.PutUint16(p[103:105], uint16(w.off))
	cellPtrArea := 108
	for i := 0; i < n; i++ {
		_ = i
	}
	binary.BigEndian.PutUint16(p[107:109], 0)
	copy(p[w.off:], w.page[w.off:pgSize])
	writePage1(w.f, p)
}

func writePage1(f *os.File, p []byte) {
	hdr := make([]byte, 100)
	copy(hdr[0:16], "SQLite format 3\x00")
	binary.BigEndian.PutUint16(hdr[16:18], 4096>>8)
	hdr[18] = 1
	hdr[19] = 1
	hdr[20] = 64
	hdr[21] = 32
	hdr[22] = 32
	hdr[23] = 32
	binary.BigEndian.PutUint32(hdr[24:28], 1)
	binary.BigEndian.PutUint32(hdr[28:32], 0)
	binary.BigEndian.PutUint32(hdr[40:44], 0)
	binary.BigEndian.PutUint32(hdr[44:48], 0)
	hdr[92] = 0
	copy(p[0:100], hdr)
	f.Write(p)
}

func (w *sqliteWriter) insertRow(vals []sqliteVal) {
	w.pageNo++
	rec := sqliteRecord(vals)
	cell := appendVarint(nil, uint64(len(rec)))
	cell = append(cell, appendVarint(nil, uint64(w.rows+1))...)
	cell = append(cell, rec...)
	if w.page == nil {
		w.page = make([]byte, pgSize)
		w.off = pgSize
		w.rows = 0
	}
	w.cellOff = w.off - len(cell)
	copy(w.page[w.cellOff:], cell)
	w.off = w.cellOff
	w.rows++
	if w.off < 200 {
		w.flushDataPage()
	}
}

func (w *sqliteWriter) flushDataPage() {
	p := make([]byte, pgSize)
	p[0] = 13
	binary.BigEndian.PutUint16(p[1:3], uint16(w.off))
	binary.BigEndian.PutUint16(p[3:5], 0)
	binary.BigEndian.PutUint16(p[5:7], uint16(w.rows))
	binary.BigEndian.PutUint16(p[7:9], 0)
	copy(p[w.off:], w.page[w.off:pgSize])
	w.f.Write(p)
	w.page = make([]byte, pgSize)
	w.off = pgSize
	w.rows = 0
}

func (w *sqliteWriter) finish() {
	if w.rows > 0 && w.pageNo > 0 {
		w.flushDataPage()
	}
}
