	off    int // offset within page where next cell is written (from end)
	rows   int
	pageNo int
}

const pgSize = 4096

func newSQLite(f *os.File) *sqliteWriter {
	return &sqliteWriter{f: f, pageNo: 0}
}

func (w *sqliteWriter) createTable(name, sql string) {
	// pages: 1 = sqlite_master leaf, 2.. = table leaf
	w.f.Truncate(0)
	w.page = make([]byte, pgSize)
	// page 1 header written at finish
	w.off = pgSize
	w.rows = 0
	// add the schema row
	w.addRow(sqliteRecord([]sqliteVal{
		{text: "table"}, {text: name}, {int: 2}, {text: sql},
	}))
	w.flushMaster()
}

func sqliteRecord(vals []sqliteVal) []byte {
	var body []byte
	var hdr []byte
	for _, v := range vals {
		if v.isNull {
			hdr = appendVarint(hdr, 0)
			continue
		}
		if v.text != "" {
			hdr = appendVarint(hdr, uint64(len(v.text)*2+13))
			body = append(body, v.text...)
			continue
		}
		if v.real != 0 || math.IsNaN(v.real) {
			hdr = appendVarint(hdr, 7)
			b := make([]byte, 8)
			binary.BigEndian.PutUint64(b, math.Float64bits(v.real))
			body = append(body, b...)
			continue
		}
		// integer
		i := v.int
		switch {
		case i == 0:
			hdr = appendVarint(hdr, 8)
		case i == 1:
			hdr = appendVarint(hdr, 9)
		case i >= -128 && i <= 127:
			hdr = appendVarint(hdr, 1)
			body = append(body, byte(i))
		case i >= -32768 && i <= 32767:
			hdr = appendVarint(hdr, 2)
			b := make([]byte, 2)
			binary.BigEndian.PutUint16(b, uint16(i))
			body = append(body, b...)
		case i >= -2147483648 && i <= 2147483647:
			hdr = appendVarint(hdr, 4)
			b := make([]byte, 4)
			binary.BigEndian.PutUint32(b, uint32(i))
			body = append(body, b...)
		default:
			hdr = appendVarint(hdr, 6)
			b := make([]byte, 8)
			binary.BigEndian.PutUint64(b, uint64(i))
			body = append(body, b...)
		}
	}
	hl := len(hdr)
	hdrSize := appendVarint(nil, uint64(hl))
	rec := append(append([]byte{}, hdrSize...), hdr...)
	rec = append(rec, body...)
	return rec
}

func appendVarint(b []byte, v uint64) []byte {
	if v <= 0x7f {
		return append(b, byte(v))
	}
	if v <= 0x3fff {
		return append(b, byte((v>>7)|0x80), byte(v&0x7f))
	}
	var tmp []byte
	for v > 0 {
		tmp = append([]byte{byte(v & 0x7f)}, tmp...)
		v >>= 7
	}
	for i := 0; i < len(tmp)-1; i++ {
		tmp[i] |= 0x80
	}
	return append(b, tmp...)
}

func (w *sqliteWriter) addRow(rec []byte) {
	// leaf page cell: varint payload len, varint rowid, payload
	cell := appendVarint(nil, uint64(len(rec)))
	cell = append(cell, appendVarint(nil, uint64(w.rows+1))...)
	cell = append(cell, rec...)
	w.cellOff = pgSize - len(cell)
	copy(w.page[w.cellOff:], cell)
	w.off = w.cellOff
	w.rows++
}

func (w *sqliteWriter) flushMaster() {
	// page 1: btree leaf for sqlite_master
	p := make([]byte, pgSize)
	p[100] = 13 // leaf table
	binary.BigEndian.PutUint16(p[103:105], uint16(pgSize))
	binary.BigEndian.PutUint32(p[28:32], 0)
	binary.BigEndian.PutUint16(p[105:107], 0)
	binary.BigEndian.PutUint16(p[106:108], uint16(w.off))
	binary.BigEndian.PutUint16(p[103:105], uint16(w.off))
	n := w.rows
	binary.BigEndian.PutUint16(p[103:105], uint16(w.off))
	cellPtrArea := 108
	for i := 0; i < n; i++ {
		_ = i
	}
	binary.BigEndian.PutUint16(p[107:109], 0)
	copy(p[w.off:], w.page[w.off:pgSize])
	writePage1(w.f, p)
}

func writePage1(f *os.File, p []byte) {
	hdr := make([]byte, 100)
	copy(hdr[0:16], "SQLite format 3\x00")
	binary.BigEndian.PutUint16(hdr[16:18], 4096>>8)
	hdr[18] = 1
	hdr[19] = 1
	hdr[20] = 64
	hdr[21] = 32
	hdr[22] = 32
	hdr[23] = 32
	binary.BigEndian.PutUint32(hdr[24:28], 1)
	binary.BigEndian.PutUint32(hdr[28:32], 0)
	binary.BigEndian.PutUint32(hdr[40:44], 0)
	binary.BigEndian.PutUint32(hdr[44:48], 0)
	hdr[92] = 0
	copy(p[0:100], hdr)
	f.Write(p)
}

func (w *sqliteWriter) insertRow(vals []sqliteVal) {
	w.pageNo++
	rec := sqliteRecord(vals)
	cell := appendVarint(nil, uint64(len(rec)))
	cell = append(cell, appendVarint(nil, uint64(w.rows+1))...)
	cell = append(cell, rec...)
	if w.page == nil {
		w.page = make([]byte, pgSize)
		w.off = pgSize
		w.rows = 0
	}
	w.cellOff = w.off - len(cell)
	copy(w.page[w.cellOff:], cell)
	w.off = w.cellOff
	w.rows++
	if w.off < 200 {
		w.flushDataPage()
	}
}

func (w *sqliteWriter) flushDataPage() {
	p := make([]byte, pgSize)
	p[0] = 13
	binary.BigEndian.PutUint16(p[1:3], uint16(w.off))
	binary.BigEndian.PutUint16(p[3:5], 0)
	binary.BigEndian.PutUint16(p[5:7], uint16(w.rows))
	binary.BigEndian.PutUint16(p[7:9], 0)
	copy(p[w.off:], w.page[w.off:pgSize])
	w.f.Write(p)
	w.page = make([]byte, pgSize)
	w.off = pgSize
	w.rows = 0
}

func (w *sqliteWriter) finish() {
	if w.rows > 0 && w.pageNo > 0 {
		w.flushDataPage()
	}
}
