package main

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"
)

// arg kinds
const (
	kindFlag = iota
	kindU64
	kindU32
	kindF64
	kindDur
	kindStr
	kindEnum
	kindMethod
)

type argSpec struct {
	short    string
	long     string
	valName  string
	kind     int
	multi    bool
	possible []string
}

type parsed struct {
	vals map[string][]string
	url  string
}

var specs []argSpec

func init() {
	specs = []argSpec{
		{short: "n", valName: "N_REQUESTS", kind: kindU64},
		{short: "c", valName: "N_CONNECTIONS", kind: kindU64},
		{short: "p", valName: "N_HTTP2_PARALLEL", kind: kindU64},
