		{long: "aws-sigv4", valName: "AWS_SIGV4", kind: kindStr},
		{short: "x", valName: "PROXY", kind: kindStr},
		{long: "proxy-http-version", valName: "PROXY_HTTP_VERSION", kind: kindStr},
		{long: "proxy-http2", kind: kindFlag},
		{long: "http-version", valName: "HTTP_VERSION", kind: kindStr},
		{long: "http2", kind: kindFlag},
		{long: "host", valName: "HOST", kind: kindStr},
		{long: "disable-compression", kind: kindFlag},
		{short: "r", long: "redirect", valName: "REDIRECT", kind: kindU32},
		{long: "disable-keepalive", kind: kindFlag},
		{long: "no-pre-lookup", kind: kindFlag},
		{long: "ipv6", kind: kindFlag},
		{long: "ipv4", kind: kindFlag},
		{long: "cacert", valName: "CACERT", kind: kindStr},
		{long: "cert", valName: "CERT", kind: kindStr},
		{long: "key", valName: "KEY", kind: kindStr},
		{long: "insecure", kind: kindFlag},
		{long: "connect-to", valName: "CONNECT_TO", kind: kindStr, multi: true},
		{long: "no-color", kind: kindFlag},
		{long: "unix-socket", valName: "UNIX_SOCKET", kind: kindStr},
		{long: "stats-success-breakdown", kind: kindFlag},
		{long: "db-url", valName: "DB_URL", kind: kindStr},
		{long: "debug", kind: kindFlag},
		{short: "o", long: "output", valName: "OUTPUT", kind: kindStr},
		{long: "output-format", valName: "OUTPUT_FORMAT", kind: kindEnum, possible: []string{"text", "json", "csv", "quiet"}},
		{short: "u", long: "time-unit", valName: "TIME_UNIT", kind: kindEnum, possible: []string{"ns", "us", "ms", "s", "m", "h"}},
		{short: "h", long: "help", kind: kindFlag},
		{short: "V", long: "version", kind: kindFlag},
	}
}

var conflicts = [][2]string{
	{"z", "n"},
	{"burst-delay", "q"},
}

var requires = map[string]string{
	"burst-delay": "burst-rate",
	"cert":        "key",
	"key":         "cert",
}

func specIndex(short, long string) int {
	for i, s := range specs {
		if short != "" && s.short == short {
			return i
		}
		if long != "" && s.long == long {
			return i
		}
	}
	return -1
}

func specByName(name string) int {
	if idx := specIndex(name, ""); idx >= 0 {
		return idx
	}
	return specIndex("", name)
}

func binName() string {
	a := os.Args
	if len(a) == 0 {
		return "oha"
	}
	return filepath.Base(a[0])
}

func errExit(msg string) {
	fmt.Fprint(os.Stderr, msg)
	os.Exit(2)
}

func (p *parsed) has(name string) bool {
	_, ok := p.vals[name]
	return ok
}

func (p *parsed) one(name string) (string, bool) {
	v, ok := p.vals[name]
	if !ok || len(v) == 0 {
		return "", false
	}
	return v[len(v)-1], true
}

func (p *parsed) all(name string) []string {
	return p.vals[name]
}

func pos(list []string, s string) int {
	for i, v := range list {
		if v == s {
			return i
		}
	}
	return -1
}

func specName(i int) string {
	s := specs[i]
	if s.short != "" {
		return s.short
	}
	return s.long
}

func argDisplay(idx int) string {
	s := specs[idx]
	if s.valName != "" {
		if s.long != "" {
			return fmt.Sprintf("--%s <%s>", s.long, s.valName)
		}
		return fmt.Sprintf("-%s <%s>", s.short, s.valName)
	}
	if s.long != "" {
		return "--" + s.long
	}
	return "-" + s.short
}

func argUsage(s argSpec) string {
	if s.valName != "" {
		if s.long != "" {
			return fmt.Sprintf("--%s <%s>", s.long, s.valName)
		}
		return fmt.Sprintf("-%s <%s>", s.short, s.valName)
	}
	if s.long != "" {
		return "--" + s.long
	}
	return "-" + s.short
}

// usageFor builds "Usage: bin <args> <URL>" from used args in declaration order
func usageFor(used []string, skip map[string]bool) string {
	var parts []string
	seen := map[int]bool{}
	add := func(idx int) {
		if seen[idx] {
			return
		}
		seen[idx] = true
		parts = append(parts, argUsage(specs[idx]))
	}
	for i := range specs {
		name := specName(i)
		if skip != nil && skip[name] {
			continue
		}
		if pos(used, name) >= 0 {
			add(i)
			continue
		}
		if req, ok := requires[name]; ok && pos(used, name) >= 0 {
			add(i)
			if pos(used, req) < 0 && !(skip != nil && skip[req]) {
				if ri := specByName(req); ri >= 0 {
					add(ri)
				}
			}
		}
	}
	parts = append(parts, "<URL>")
	return "Usage: " + binName() + " " + strings.Join(parts, " ")
}

func (p *parsed) missingRequiredUsage(used []string, missing []string) string {
	var parts []string
	seen := map[int]bool{}
	render := func(idx int) {
		if seen[idx] {
			return
		}
		seen[idx] = true
		parts = append(parts, argUsage(specs[idx]))
	}
	for i := range specs {
		name := specName(i)
		isUsed := pos(used, name) >= 0
		if req, ok := requires[name]; ok && isUsed {
			render(i)
			if pos(used, req) < 0 {
				if ri := specByName(req); ri >= 0 {
					render(ri)
				}
			}
			continue
		}
		if isUsed {
			render(i)
			continue
		}
		for _, mi := range missing {
			if mi == name {
				render(i)
			}
		}
	}
	parts = append(parts, "<URL>")
	return "Usage: " + binName() + " " + strings.Join(parts, " ")
}

func similarArg(name string) string {
	best := ""
	bestScore := 999
	for _, s := range specs {
		if s.long == "" {
			continue
		}
		d := editDistance(name, s.long)
		if d < bestScore {
			bestScore = d
			best = s.long
		}
	}
	if bestScore <= 2 && best != name {
		return "--" + best
	}
	return ""
}

func editDistance(a, b string) int {
	if a == b {
		return 0
	}
	la, lb := len(a), len(b)
	prev := make([]int, lb+1)
	cur := make([]int, lb+1)
	for j := 0; j <= lb; j++ {
		prev[j] = j
	}
	for i := 1; i <= la; i++ {
		cur[0] = i
		for j := 1; j <= lb; j++ {
			cost := 1
			if a[i-1] == b[j-1] {
				cost = 0
			}
			cur[j] = min3(prev[j]+1, cur[j-1]+1, prev[j-1]+cost)
		}
		copy(prev, cur)
	}
	return prev[lb]
}

func min3(a, b, c int) int {
	if b < a {
		a = b
	}
	if c < a {
		a = c
	}
	return a
}
