	}
	return "-" + s.short
}

// usageFor builds "Usage: bin <args> <URL>" from used args in declaration order
func usageFor(used []string, skip map[string]bool) string {
	var parts []string
	seen := map[int]bool{}
	add := func(idx int) {
		if seen[idx] {
			return
		}
		seen[idx] = true
		parts = append(parts, argUsage(specs[idx]))
	}
	for i := range specs {
		name := specName(i)
		if skip != nil && skip[name] {
			continue
		}
		if pos(used, name) >= 0 {
			add(i)
			continue
		}
		if req, ok := requires[name]; ok && pos(used, name) >= 0 {
			add(i)
			if pos(used, req) < 0 && !(skip != nil && skip[req]) {
				if ri := specByName(req); ri >= 0 {
					add(ri)
				}
			}
		}
	}
	parts = append(parts, "<URL>")
	return "Usage: " + binName() + " " + strings.Join(parts, " ")
}

func (p *parsed) missingRequiredUsage(used []string, missing []string) string {
	var parts []string
	seen := map[int]bool{}
	render := func(idx int) {
		if seen[idx] {
			return
		}
		seen[idx] = true
		parts = append(parts, argUsage(specs[idx]))
	}
	for i := range specs {
		name := specName(i)
		isUsed := pos(used, name) >= 0
		if req, ok := requires[name]; ok && isUsed {
			render(i)
			if pos(used, req) < 0 {
				if ri := specByName(req); ri >= 0 {
					render(ri)
				}
			}
			continue
		}
		if isUsed {
			render(i)
			continue
		}
		for _, mi := range missing {
			if mi == name {
				render(i)
			}
		}
	}
	parts = append(parts, "<URL>")
	return "Usage: " + binName() + " " + strings.Join(parts, " ")
}

func similarArg(name string) string {
	best := ""
	bestScore := 999
	for _, s := range specs {
		if s.long == "" {
			continue
		}
		d := editDistance(name, s.long)
		if d < bestScore {
			bestScore = d
			best = s.long
		}
	}
	if bestScore <= 2 && best != name {
		return "--" + best
	}
	return ""
}

func editDistance(a, b string) int {
	if a == b {
		return 0
	}
	la, lb := len(a), len(b)
	prev := make([]int, lb+1)
	cur := make([]int, lb+1)
	for j := 0; j <= lb; j++ {
		prev[j] = j
	}
	for i := 1; i <= la; i++ {
		cur[0] = i
		for j := 1; j <= lb; j++ {
			cost := 1
			if a[i-1] == b[j-1] {
				cost = 0
			}
			cur[j] = min3(prev[j]+1, cur[j-1]+1, prev[j-1]+cost)
		}
		copy(prev, cur)
	}
	return prev[lb]
}

func min3(a, b, c int) int {
	if b < a {
		a = b
	}
	if c < a {
		a = c
	}
	return a
}
