{"command": "cd /workspace/src && cat > tui.go <<'GOEOF'
package main

import (
	"fmt"
	"math"
	"os"
	"strings"
	"sync"
	"syscall"
	"time"
	"unsafe"
)

type cell struct {
	ch  rune
	fg  string // escape seq for fg
}

type screen struct {
	w, h int
	cells [][]cell
}

func newScreen(w, h int) *screen {
	s := &screen{w: w, h: h}
	s.cells = make([][]cell, h)
	for i := range s.cells {
		s.cells[i] = make([]cell, w)
		for j := range s.cells[i] {
			s.cells[i][j] = cell{ch: ' '}
		}
	}
	return s
}

const (
	boxTL = '\u250c'
	boxTR = '\u2510'
	boxBL = '\u2514'
	boxBR = '\u2518'
	boxH  = '\u2500'
	boxV  = '\u2502'
)

func (s *screen) block(x, y, w, h int, title string, fg string) {
	if w < 2 || h < 2 {
		return
	}
	for i := 0; i < w; i++ {
		s.set(x+i, y, boxH, fg)
		s.set(x+i, y+h-1, boxH, fg)
	}
	for j := 0; j < h; j++ {
		s.set(x, y+j, boxV, fg)
		s.set(x+w-1, y+j, boxV, fg)
	}
	s.set(x, y, boxTL, fg)
	s.set(x+w-1, y, boxTR, fg)
	s.set(x, y+h-1, boxBL, fg)
	s.set(x+w-1, y+h-1, boxBR, fg)
	if title != "" {
		t := title
		if len([]rune(t)) > w-2 {
			r := []rune(t)
			t = string(r[:w-2])
		}
		for i, ch := range t {
			s.set(x+1+i, y, ch, fg)
		}
	}
}

func (s *screen) set(x, y int, ch rune, fg string) {
	if x < 0 || y < 0 || x >= s.w || y >= s.h {
		return
	}
	s.cells[y][x] = cell{ch: ch, fg: fg}
}

func (s *screen) text(x, y int, str string, fg string) {
	i := 0
	for _, ch := range str {
		s.set(x+i, y, ch, fg)
		i++
	}
}

func (s *screen) fill(x, y, w, h int, ch rune, fg string) {
	for j := 0; j < h; j++ {
		for i := 0; i < w; i++ {
			s.set(x+i, y+j, ch, fg)
		}
	}
}

func (s *screen) render(sb *strings.Builder) {
	for j := 0; j < s.h; j++ {
		lastFg := ""
		for i := 0; i < s.w; i++ {
			c := s.cells[j][i]
			if c.fg != lastFg {
				if c.fg == "" {
					sb.WriteString("\x1b[39m")
				} else {
					sb.WriteString(c.fg)
				}
				lastFg = c.fg
			}
			sb.WriteRune(c.ch)
		}
		if lastFg != "" {
			sb.WriteString("\x1b[39m")
		}
		if j < s.h-1 {
			sb.WriteString("\r\n")
		}
	}
}

// terminal raw mode helpers
type termios struct {
	Iflag, Oflag, Cflag, Lflag uint32
	Line                       byte
	Cc                         [32]byte
	Ispeed, Ospeed             uint32
}

const (
	tcgets = 0x5401
	tcsets = 0x5402
)

func ioctlTermios(fd int, req uintptr, t *termios) error {
	_, _, e := syscall.Syscall(syscall.SYS_IOCTL, uintptr(fd), req, uintptr(unsafe.Pointer(t)))
	if e != 0 {
		return e
	}
	return nil
}

type winsize struct {
	Row, Col, Xpixel, Ypixel uint16
}

func terminalSize() (int, int, error) {
	var ws winsize
	_, _, e := syscall.Syscall(syscall.SYS_IOCTL, uintptr(0), uintptr(syscall.TIOCGWINSZ), uintptr(unsafe.Pointer(&ws)))
	if e != 0 {
		return 80, 24, e
	}
	return int(ws.Col), int(ws.Row), nil
}

type tui struct {
	cfg        *config
	st         *stats
	mu         *sync.Mutex
	w, h       int
	bucket     time.Duration
	bucketSet  bool
	quit       bool
	oldTermios termios
	rawSet     bool
	out        *os.File
	startT     time.Time
}

func runTUI(c *config, st *stats, mu *sync.Mutex, startT time.Time) {
	t := &tui{cfg: c, st: st, mu: mu, out: os.Stdout, startT: startT}
	t.setup()
	defer t.restore()
	go t.readKeys()
	frame := time.Second / time.Duration(c.fps)
	if frame <= 0 {
		frame = 62 * time.Millisecond
	}
	ticker := time.NewTicker(frame)
	defer ticker.Stop()
	for !t.quit {
		<-ticker.C
		t.draw()
	}
}

func (t *tui) setup() {
	fmt.Fprint(t.out, "\x1b[?1049h\x1b[H\x1b[?25l")
	t.out.Sync()
	if err := ioctlTermios(0, tcgets, &t.oldTermios); err == nil {
		nt := t.oldTermios
		nt.Lflag &^= 0x8 | 0x1 | 0x2 | 0x20 // ICANON|ECHO|ISIG|IEXTEN
		nt.Cflag &^= 0x100                  // CSIZE mask part
		nt.Cflag |= 0                       // raw
		nt.Cc[6] = 1                        // VMIN
		nt.Cc[5] = 0                        // VTIME
		ioctlTermios(0, tcsets, &nt)
		t.rawSet = true
	}
	t.resize()
}

func (t *tui) resize() {
	w, h, err := terminalSize()
	if err != nil || w == 0 {
		w, h = 80, 24
	}
	t.w, t.h = w, h
}

func (t *tui) restore() {
	if t.rawSet {
		ioctlTermios(0, tcsets, &t.oldTermios)
	}
	fmt.Fprint(t.out, "\x1b[?25h\x1b[?1049l\x1b[0m")
	t.out.Sync()
}

func (t *tui) readKeys() {
	buf := make([]byte, 64)
	for {
		n, err := os.Stdin.Read(buf)
		if err != nil {
			return
		}
		for i := 0; i < n; i++ {
			b := buf[i]
			if b == 'q' || b == 3 || b == 27 {
				t.mu.Lock()
				t.quit = true
				t.mu.Unlock()
				return
			}
			if b == '-' || b == '+' || b == 'a' {
				t.mu.Lock()
				if b == 'a' {
					t.bucketSet = false
				} else {
					if t.bucket == 0 {
						t.bucket = time.Millisecond
					}
					if b == '-' {
						t.bucket = t.bucket / 10
						if t.bucket < time.Millisecond {
							t.bucket = time.Millisecond
						}
					} else {
						t.bucket = t.bucket * 10
						if t.bucket > 3600*time.Second {
							t.bucket = 3600 * time.Second
						}
					}
					t.bucketSet = true
				}
				t.mu.Unlock()
			}
		}
	}
}

func fmtBucketName(d time.Duration) string {
	if d == 0 {
		return "ms"
	}
	ns := d.Nanoseconds()
	switch {
	case ns < 1000000:
		return "ms"
	case ns < 1000000000:
		if ns/1000000 == 1 {
			return "ms"
		}
		return fmt.Sprintf("%d ms", ns/1000000)
	default:
