func maxSec(v float64) float64 {
	if math.IsNaN(v) || math.IsInf(v, 0) {
		return v
	}
	return v
}

func fmtSecs(v float64) string {
	if math.IsNaN(v) {
		return "NaN secs"
	}
	if math.IsInf(v, 1) {
		return "inf secs"
	}
	if math.IsInf(v, -1) {
		return "-inf secs"
	}
	return fmt.Sprintf("%.4f secs", v)
}

func maxLabelWidth(bucket time.Duration) int {
	ns := bucket.Nanoseconds()
	if ns < 1000000 {
		return 3 // e.g. "6ms"
	}
	sec := ns / 1000000000
	if sec < 10 {
		return 2 // "7s"
	}
	if sec < 100 {
		return 3 // "60s"
	}
	return 4
}

func requestsInWindow(st *stats, bucket time.Duration) int {
	cut := time.Since(tuiStart) - bucket
	n := 0
	for i := len(st.records) - 1; i >= 0; i-- {
		r := st.records[i]
		if r.end < cut.Seconds() {
			break
		}
		if r.err == "" {
			n++
		}
	}
	return n
}

func maxInWindow(st *stats, bucket time.Duration) float64 {
	cut := time.Since(tuiStart) - bucket
	var mx float64 = math.Inf(-1)
	for _, r := range st.records {
		if r.err != "" {
			continue
		}
		if r.end < cut.Seconds() {
			continue
		}
		if r.duration > mx {
			mx = r.duration
		}
	}
	return mx
}

func minInWindow(st *stats, bucket time.Duration) float64 {
	cut := time.Since(tuiStart) - bucket
	var mn float64 = math.Inf(1)
	for _, r := range st.records {
		if r.err != "" {
			continue
		}
		if r.end < cut.Seconds() {
			continue
		}
		if r.duration < mn {
			mn = r.duration
		}
	}
	return mn
}

func avgInWindow(st *stats, bucket time.Duration) float64 {
	cut := time.Since(tuiStart) - bucket
	sum := 0.0
	n := 0
	for _, r := range st.records {
		if r.err != "" {
			continue
		}
		if r.end < cut.Seconds() {
			continue
		}
		sum += r.duration
		n++
	}
	if n == 0 {
		return math.NaN()
	}
	return sum / float64(n)
}

func dataInWindow(st *stats, bucket time.Duration) uint64 {
	cut := time.Since(tuiStart) - bucket
	var sum uint64
	for _, r := range st.records {
		if r.err != "" {
			continue
		}
		if r.end < cut.Seconds() {
			continue
		}
		sum += r.bytes
	}
	return sum
}

var tuiStart time.Time

// rpsBuckets returns newest-first bucket counts and labels
func rpsBuckets(st *stats, bucket time.Duration, n int, elapsed float64) ([]float64, []string) {
	vals := make([]float64, n)
	now := elapsed
	b := bucket.Seconds()
	for _, r := range st.records {
		if r.err != "" {
			continue
		}
		age := now - r.end
		if age < 0 {
			age = 0
		}
		idx := int(age / b)
		if idx < 0 {
			idx = 0
		}
		if idx >= n {
			continue
		}
		vals[idx]++
	}
	labels := make([]string, n)
	for i := 0; i < n; i++ {
		labels[i] = ageLabel(i, bucket)
	}
	return vals, labels
}

func ageLabel(i int, bucket time.Duration) string {
	ns := bucket.Nanoseconds()
	if ns < 1000000 {
		return fmt.Sprintf("%dms", i*int(ns/1000000))
	}
	sec := ns / 1000000000
	return fmt.Sprintf("%ds", i*int(sec))
}

func latencyBuckets(d *dist, n int) ([]float64, []string) {
	vals := make([]float64, n)
	labels := make([]string, n)
	if d.n() == 0 {
		for i := 0; i < n; i++ {
			labels[i] = "NaN"
		}
		return vals, labels
	}
	mn := d.min()
	mx := d.max()
	span := mx - mn
	s := d.sortVals()
	for _, v := range s {
		idx := 0
		if span > 0 {
			idx = int(math.Floor((v - mn) / span * float64(n-1)))
			if idx < 0 {
				idx = 0
			}
			if idx > n-1 {
				idx = n - 1
			}
		}
		vals[idx]++
	}
	for i := 0; i < n; i++ {
		var bound float64
		if i == n-1 {
			bound = mx
		} else {
			bound = mn + span/float64(n-1)*float64(i)
		}
		labels[i] = fmt.Sprintf("%.4f", bound)
	}
	return vals, labels
}
