{"command": "cd /workspace/src && cat >> tui.go <<'GOEOF'

func openFileCount() (int, uint64) {
	n := 0
	if ents, err := os.ReadDir("/proc/self/fd"); err == nil {
		n = len(ents)
	}
	var lim uint64 = 1024
	var rl syscall.Rlimit
	if err := syscall.Getrlimit(syscall.RLIMIT_NOFILE, &rl); err == nil {
		lim = rl.Cur
	}
	return n, lim
}

func (t *tui) draw() {
	t.mu.Lock()
	defer t.mu.Unlock()
	t.resize()
	s := newScreen(t.w, t.h)
	elapsed := time.Since(t.startT).Seconds()
	// bucket
	bucket := t.bucket
	if !t.bucketSet {
		if elapsed < 1 {
			bucket = time.Millisecond
		} else {
			p := math.Floor(math.Log10(elapsed))
			bucket = time.Duration(math.Pow(10, p) * float64(time.Second))
			if bucket < time.Millisecond {
				bucket = time.Millisecond
			}
		}
	}
	unit := pickUnit(maxSec(t.st.latency.max()) * 1e9)
	_ = unit
	// layout
	progH := 3
	statsH := 8
	var errLines []string
	for _, e := range sortedErrors(t.st) {
		errLines = append(errLines, fmt.Sprintf("[%d] %s", t.st.errDist[e], e))
	}
	errH := 2 + len(errLines)
	if errH < 2 {
		errH = 2
	}
	chartY := progH + statsH + errH
	chartH := t.h - chartY
	if chartH < 3 {
		chartH = 3
	}
	// progress block
	s.block(0, 0, t.w, progH, "Progress", "")
	inner := t.w - 2
	ratio := 0.0
	var label string
	if t.cfg.useDuration {
		total := t.cfg.duration.Seconds()
		ratio = elapsed / total
		label = fmt.Sprintf("%ds / %ds", int(elapsed), int(total))
	} else {
		total := float64(t.cfg.nRequests)
		done := float64(t.st.success + t.st.errCount + t.st.deadlineAborts)
		ratio = done / total
		label = fmt.Sprintf("%d / %d", int(done), int(total))
	}
	if ratio < 0 {
		ratio = 0
	}
	if ratio > 1 {
		ratio = 1
	}
	fill := int(ratio * float64(inner))
	for i := 0; i < inner; i++ {
		ch := ' '
		if i < fill {
			ch = '\u2588'
		}
		s.set(1+i, 1, ch, "\x1b[38;5;6m")
	}
	// label centered
	lx := 1 + (inner-len([]rune(label)))/2
	s.text(lx, 1, label, "\x1b[38;5;6m")
	// stats row
	leftW := t.w / 2
	rightW := t.w - leftW
	s.block(0, progH, leftW, statsH, "Stats for last "+fmtBucketName(bucket), "")
	s.block(leftW, progH, rightW, statsH, "Status code distribution", "")
	// stats lines
	reqs := requestsInWindow(t.st, bucket)
	slow := maxInWindow(t.st, bucket)
	fast := minInWindow(t.st, bucket)
	avg := avgInWindow(t.st, bucket)
	data := dataInWindow(t.st, bucket)
	nf, lim := openFileCount()
	s.text(1, progH+1, fmt.Sprintf("Requests : %d", reqs), "")
	s.text(1, progH+2, fmt.Sprintf("Slowest: %s", fmtSecs(slow)), "\x1b[38;5;3m")
	s.text(1, progH+3, fmt.Sprintf("Fastest: %s", fmtSecs(fast)), "\x1b[38;5;2m")
	s.text(1, progH+4, fmt.Sprintf("Average: %s", fmtSecs(avg)), "\x1b[38;5;6m")
	s.text(1, progH+5, fmt.Sprintf("Data: %s", formatBytes(float64(data))), "")
	s.text(1, progH+6, fmt.Sprintf("Number of open files: %d / %d", nf, lim), "")
	// status code distribution
	row := progH + 1
	for _, code := range sortedCodes(t.st) {
		if row >= progH+statsH-1 {
			break
		}
		s.text(1+leftW, row, fmt.Sprintf("[%d] %d responses", code, t.st.statusCodes[code]), "")
		row++
	}
	// error distribution
	s.block(0, progH+statsH, t.w, errH, "Error distribution", "")
	for i, l := range errLines {
		s.text(1, progH+statsH+1+i, l, "")
	}
	// charts
	leftH := chartH
	s.block(0, chartY, leftW, leftH, "Requests / past "+fmtBucketName(bucket)+" (auto). press -/+/a to change", "\x1b[38;5;2m")
	s.block(leftW, chartY, rightW, leftH, "Response time histogram", "\x1b[38;5;3m")
	// left chart: rps buckets
	innerLW := leftW - 2
	innerLH := leftH - 2
	if innerLH >= 2 {
		maxLabel := maxLabelWidth(bucket)
		barW := maxLabel + 3
		n := (innerLW + 1) / (barW + 1)
		if n < 1 {
			n = 1
		}
		vals, labels := rpsBuckets(t.st, bucket, n, elapsed)
		maxV := 0.0
		for _, v := range vals {
			if v > maxV {
				maxV = v
			}
		}
		s.barChart(1, chartY+1, innerLW, innerLH-1, vals, labels, "\x1b[38;5;2m", maxV, true)
	}
	// right chart: latency histogram
	innerRW := rightW - 2
	innerRH := leftH - 2
	if innerRH >= 2 {
		hd := t.st.latency
		if t.st.success == 0 {
			hd = dist{}
		}
		n := (innerRW + 1) / 8
		if n < 1 {
			n = 1
		}
		vals, labels := latencyBuckets(&hd, n)
		maxV := 0.0
		for _, v := range vals {
			if v > maxV {
				maxV = v
			}
		}
		s.barChart(1+leftW, chartY+1, innerRW, innerRH-1, vals, labels, "\x1b[38;5;3m", maxV, true)
	}
	var sb strings.Builder
	s.render(&sb)
	fmt.Fprint(t.out, "\x1b[H"+sb.String())
	t.out.Sync()
}

func maxSec(v float64) float64 {
	if math.IsNaN(v) || math.IsInf(v, 0) {
		return v
	}
	return v
}

func fmtSecs(v float64) string {
	if math.IsNaN(v) {
		return "NaN secs"
	}
	if math.IsInf(v, 1) {
		return "inf secs"
	}
	if math.IsInf(v, -1) {
		return "-inf secs"
	}
	return fmt.Sprintf("%.4f secs", v)
}

func maxLabelWidth(bucket time.Duration) int {
	ns := bucket.Nanoseconds()
	if ns < 1000000 {
		return 3 // e.g. "6ms"
	}
	sec := ns / 1000000000
	if sec < 10 {
		return 2 // "7s"
	}
	if sec < 100 {
		return 3 // "60s"
	}
	return 4
}

func requestsInWindow(st *stats, bucket time.Duration) int {
	cut := time.Since(tuiStart) - bucket
	n := 0
	for i := len(st.records) - 1; i >= 0; i-- {
		r := st.records[i]
		if r.end < cut.Seconds() {
			break
		}
		if r.err == "" {
			n++
		}
	}
	return n
}

func maxInWindow(st *stats, bucket time.Duration) float64 {
	cut := time.Since(tuiStart) - bucket
	var mx float64 = math.Inf(-1)
	for _, r := range st.records {
		if r.err != "" {
			continue
		}
		if r.end < cut.Seconds() {
			continue
		}
		if r.duration > mx {
			mx = r.duration
		}
	}
	return mx
}

func minInWindow(st *stats, bucket time.Duration) float64 {
	cut := time.Since(tuiStart) - bucket
	var mn float64 = math.Inf(1)
	for _, r := range st.records {
		if r.err != "" {
			continue
		}
		if r.end < cut.Seconds() {
			continue
		}
		if r.duration < mn {
			mn = r.duration
		}
	}
	return mn
}

func avgInWindow(st *stats, bucket time.Duration) float64 {
	cut := time.Since(tuiStart) - bucket
	sum := 0.0
	n := 0
	for _, r := range st.records {
		if r.err != "" {
			continue
		}
		if r.end < cut.Seconds() {
			continue
		}
		sum += r.duration
		n++
	}
	if n == 0 {
		return math.NaN()
	}
	return sum / float64(n)
}

func dataInWindow(st *stats, bucket time.Duration) uint64 {
	cut := time.Since(tuiStart) - bucket
	var sum uint64
	for _, r := range st.records {
		if r.err != "" {
			continue
		}
		if r.end < cut.Seconds() {
			continue
		}
		sum += r.bytes
	}
	return sum
}

var tuiStart time.Time

// rpsBuckets returns newest-first bucket counts and labels
func rpsBuckets(st *stats, bucket time.Duration, n int, elapsed float64) ([]float64, []string) {
	vals := make([]float64, n)
	now := elapsed
	b := bucket.Seconds()
	for _, r := range st.records {
		if r.err != "" {
			continue
		}
		age := now - r.end
		if age < 0 {
			age = 0
		}
		idx := int(age / b)
		if idx < 0 {
			idx = 0
		}
		if idx >= n {
			continue
		}
		vals[idx]++
	}
	labels := make([]string, n)
	for i := 0; i < n; i++ {
		labels[i] = ageLabel(i, bucket)
	}
	return vals, labels
}

func ageLabel(i int, bucket time.Duration) string {
	ns := bucket.Nanoseconds()
	if ns < 1000000 {
		return fmt.Sprintf("%dms", i*int(ns/1000000))
	}
	sec := ns / 1000000000
	return fmt.Sprintf("%ds", i*int(sec))
}

func latencyBuckets(d *dist, n int) ([]float64, []string) {
	vals := make([]float64, n)
	labels := make([]string, n)
	if d.n() == 0 {
		for i := 0; i < n; i++ {
			labels[i] = "NaN"
		}
		return vals, labels
	}
	mn := d.min()
	mx := d.max()
	span := mx - mn
	s := d.sortVals()
	for _, v := range s {
		idx := 0
		if span > 0 {
			idx = int(math.Floor((v - mn) / span * float64(n-1)))
			if idx < 0 {
				idx = 0
			}
			if idx > n-1 {
				idx = n - 1
			}
		}
		vals[idx]++
	}
	for i := 0; i < n; i++ {
		var bound float64
		if i == n-1 {
			bound = mx
		} else {
			bound = mn + span/float64(n-1)*float64(i)
		}
		labels[i] = fmt.Sprintf("%.4f", bound)
	}
	return vals, labels
}
